import Foundation

/// Workroom VCS + CI status scheduling (issue #24). Split out of `AppStore` (already large) per
/// the `AppStore+WorkroomSplit.swift` convention. Best-effort / "last checked", NOT real-time:
/// statuses refresh on load, on app focus (via reload), on selection (debounced), and never via
/// a file watcher in Phase 1. The fan-out across all workrooms is bounded (so 50 workrooms
/// don't fork 50 git + 50 gh processes at once); CI is a second, slower stage that never blocks
/// the dirty dot, and is gated by a much longer TTL than the local git probe. Three separate lanes
/// here (this sweep, `scheduleSelectedStatusRefresh`, `handleWorkroomFileChange`) — plus a fourth
/// outside this file, the Changes panel's working-copy diff (`DiffResolver`) — can all reach a jj
/// snapshot for the same project concurrently; `JJSnapshotGate` (via `WorkroomStatusResolver`)
/// serializes same-project jj snapshots across ALL of them, not just within one lane.
extension AppStore {
  fileprivate static let localStatusTTL: TimeInterval = 15  // git/jj dirty/changed-files
  fileprivate static let ciStatusTTL: TimeInterval = 300  // gh CI (network)
  fileprivate static let ghStatusTTL: TimeInterval = 60  // `gh auth status` availability check
  fileprivate static let localConcurrency = 5
  fileprivate static let ciConcurrency = 2
  fileprivate static let selectionDebounce: TimeInterval = 0.3  // arrow-key row cycling coalesce

  struct StatusWorkItem: Sendable {
    let sid: SidebarID
    let path: String
    let vcs: String
    /// The colocated project root. Equals `path` for the root row; for a workroom it's the parent
    /// project's path — where stage-2 `gh` probes run for a jj workspace (which has no `.git`).
    let projectRoot: String
  }

  /// Every root + workroom as a status work item.
  func statusWorkItems() -> [StatusWorkItem] {
    var items: [StatusWorkItem] = []
    for p in projects {
      items.append(
        StatusWorkItem(sid: .root(project: p.id), path: p.path, vcs: p.vcs, projectRoot: p.path))
      for w in p.workrooms {
        // A workroom's VCS *type* is its project's (`p.vcs`) — a git project's workrooms are git
        // worktrees, a jj project's are jj workspaces. NOT `w.vcsName`, which is the workroom's
        // branch/workspace *name* (`workroom/<name>`); passing that as the type made resolveLocal
        // fall through to `.notRepository` for every workroom.
        items.append(
          StatusWorkItem(
            sid: .workroom(project: p.id, name: w.name), path: w.path, vcs: p.vcs,
            projectRoot: p.path))
      }
    }
    return items
  }

  /// Sweep every workroom's status. Cancels any in-flight sweep so a slow one can't write stale
  /// values over a newer one. `force` ignores the TTLs (e.g. a manual refresh). Two stages:
  /// fast local git/jj first, then the slow `gh` CI pass — so the dirty dots land immediately.
  func refreshWorkroomStatuses(force: Bool = false) {
    // Fixture mode never shells out to git/jj/gh — keep the deterministic seeded status (and let the
    // manual Refresh button re-apply it rather than wipe it to "unknown").
    if UITestFixture.isActive {
      seedFixtureStatuses()
      return
    }
    statusSweepTask?.cancel()
    let resolver = statusResolver
    let now = Date()
    let localTTL = Self.localStatusTTL
    let ciTTL = Self.ciStatusTTL
    let localItems = statusWorkItems().filter { item in
      // Never sweep a workroom whose setup is still writing its worktree (issue: create-time FSEvents
      // storm) — even on `force`. Its status is refreshed once, post-setup, by `createWorkroom`.
      // Covers this window's create AND another window's, since `creatingWorkrooms` is shared.
      if isCreating(item.sid) { return false }
      // Nor one whose PROJECT has a commit in flight — see `isCommittingProject`. Also honoured on
      // `force`, because a manual Refresh during a long hook races the write just as readily as the
      // timer does.
      if isCommittingProject(item.projectRoot) { return false }
      guard !force else { return true }
      guard let checked = workroomStatuses[item.sid]?.lastChecked else { return true }
      return now.timeIntervalSince(checked) >= localTTL
    }
    // `.utility` so this background sweep yields CPU to a mounting terminal surface + its login shell.
    statusSweepTask = Task(priority: .utility) { [weak self] in
      guard let self else { return }
      await self.runLocalSweep(localItems, resolver: resolver, cap: Self.localConcurrency)
      if Task.isCancelled { return }
      // Guard the network stage: if `gh` isn't installed/authenticated, skip the whole CI sweep
      // rather than spawn a `gh` per dirty workroom only to have each fail.
      await self.refreshGitHubCLI(resolver: resolver, force: force)
      if Task.isCancelled { return }
      guard self.githubCLIStatus == .available else { return }
      let ciItems = self.statusWorkItems().filter { item in
        guard let s = self.workroomStatuses[item.sid], s.dirty != nil, s.failure == nil else {
          return false
        }
        guard !force else { return true }
        guard let c = s.ciCheckedAt else { return true }
        return now.timeIntervalSince(c) >= ciTTL
      }
      if Task.isCancelled { return }
      await self.runCISweep(ciItems, resolver: resolver, cap: Self.ciConcurrency)
    }
  }

  /// Refresh `githubCLIStatus` if stale (own short TTL), so the warning + probe guards reflect
  /// whether `gh` is usable. No-ops in fixture mode (the fixture seeds `.available`).
  ///
  /// **This is the one status mutation that happens INSIDE an awaited function**, so the callers'
  /// own `Task.isCancelled` checks (`:86`/`:144`) run too late to protect it — the guard has to live
  /// here. It was missing, and that was the false, sticky "GitHub CLI not signed in": a superseded
  /// sweep or a workroom switched mid-probe SIGKILLs the `gh` child, `StatusCommandRunner`'s
  /// non-throwing continuation still hands back `exitCode: 9` with empty stdout, and the classifier
  /// read that as a logout. Publishing it then STAMPED the TTL, so the gate above turned every lane
  /// that would have healed the value into an early return for a full minute — the wrong answer
  /// suppressing its own repair, escapable only via the Refresh button's `force`.
  ///
  /// The tempting instinct — "gh's auth state is machine-global, so record it even from a cancelled
  /// task" — is wrong: a cancelled probe holds no fact at all, neither a value nor a freshness. Bail
  /// on both. Same for `.keepPrior`: leaving the stamp alone is what makes the next lane re-probe
  /// instead of trusting a non-answer.
  func refreshGitHubCLI(resolver: WorkroomStatusResolver, force: Bool = false) async {
    if UITestFixture.isActive { return }
    if !force, let at = ghStatusCheckedAt,
      Date().timeIntervalSince(at) < Self.ghStatusTTL
    {
      return
    }
    let probe = await resolver.resolveGitHubCLI()
    if Task.isCancelled { return }
    guard case .verdict(let status) = probe else { return }
    githubCLIStatus = status
    ghStatusCheckedAt = Date()
  }

  /// Freshen just the selected workroom (local + CI, forced), debounced so arrow-key cycling
  /// through rows doesn't fork a probe per row. Cancels the prior pending refresh.
  func scheduleSelectedStatusRefresh() {
    selectionStatusTask?.cancel()
    // (Re)point the filesystem watcher at the newly-selected workroom so its local status stays live
    // while you edit in its terminal (issue #24 follow-up). Cheap + safe to call on every selection.
    updateSelectedWorkroomWatch()
    // Fixture mode keeps the deterministic seeded status — selecting a target must not fork a real
    // probe that would overwrite it.
    if UITestFixture.isActive { return }
    guard let sid = selectedTargetID, let item = selectedStatusWorkItem(for: sid) else { return }
    // Don't probe a workroom whose setup is still writing its worktree — the watcher is already
    // suppressed above; this skips the debounced local+CI probe too. Re-armed post-setup by
    // `createWorkroom` calling this again once `creatingWorkrooms` no longer holds the id.
    if isCreating(sid) { return }
    // By project root, not by row: a git worktree's index and refs live in the MAIN repo, so probing
    // workroom B while workroom A of the same project commits contends on the same `index.lock`.
    if isCommittingProject(item.projectRoot) { return }
    let resolver = statusResolver
    selectionStatusTask = Task { [weak self] in
      try? await Task.sleep(nanoseconds: UInt64(Self.selectionDebounce * 1_000_000_000))
      if Task.isCancelled { return }
      guard let self else { return }
      let fresh = await resolver.resolveLocal(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
      if Task.isCancelled { return }
      self.mergeLocalStatus(fresh, into: sid)
      // Skip the network CI/PR probes when `gh` isn't usable (the inspector shows a warning instead).
      await self.refreshGitHubCLI(resolver: resolver)
      if Task.isCancelled { return }
      guard self.githubCLIStatus == .available else { return }
      // CI and the PR list are independent — run them concurrently. Apply CI the moment it lands so
      // the sidebar/tab glyph never waits on the PR probe.
      async let ciRes = resolver.resolveCI(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot, branch: fresh.branchForCI)
      async let prRawRes = resolver.resolvePRRaw(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot, branch: fresh.branchForCI)
      let ci = await ciRes
      if Task.isCancelled { return }
      self.applyCIStatus(ci, to: sid)
      let prRaw = await prRawRes
      if Task.isCancelled { return }
      self.applyPRStatus(prRaw, to: sid)
      // With the PR number in hand, fetch its checks and enrich reviewer permalinks concurrently —
      // checks must not wait behind the (conditional) reviewer-URL GraphQL round-trip (issue #75).
      guard case .info(let info) = prRaw else { return }
      async let enrichedRes = resolver.enrichPR(
        prRaw, path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
      async let checksRes = resolver.resolveChecks(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot, number: info.number)
      let enriched = await enrichedRes
      if Task.isCancelled { return }
      self.applyPRStatus(enriched, to: sid)
      let checks = await checksRes
      if Task.isCancelled { return }
      self.applyChecksStatus(checks, to: sid)
    }
  }

  /// The worst-status child of a project (root + workrooms), for the collapsed project row's
  /// aggregate badge. nil when nothing needs attention (all clean / unresolved).
  func aggregateStatus(forProject projectPath: String) -> WorkroomStatus? {
    guard let p = projects.first(where: { $0.id == projectPath }) else { return nil }
    var sids: [SidebarID] = [.root(project: p.id)]
    sids += p.workrooms.map { SidebarID.workroom(project: p.id, name: $0.name) }
    let worst = sids.compactMap { workroomStatuses[$0] }
      .max(by: { $0.aggregateWeight < $1.aggregateWeight })
    guard let worst, worst.aggregateWeight > 0 else { return nil }
    return worst
  }

  /// Run a PR write action (Phase 2b) on the selected workroom's PR: shell to `gh`, refresh the PR
  /// on success, surface `stderr` on failure. In fixture mode it optimistically updates the seeded
  /// status instead of spawning `gh`, so the actions menu is exercisable hermetically.
  func performPRAction(_ action: PRAction, number: Int, on sid: SidebarID) {
    guard let item = selectedStatusWorkItem(for: sid) else { return }
    // Flip the PR state immediately so the badge/buttons react the instant the user acts — otherwise
    // nothing visibly changes during the (multi-second) `gh` call + status re-probe, which reads as
    // "the click did nothing". Keep the prior PR to restore if `gh` fails (and in fixture mode, this
    // optimistic update *is* the result — no `gh` to confirm it).
    let priorPR = workroomStatuses[sid]?.pr
    applyOptimisticPRAction(action, on: sid)
    if UITestFixture.isActive { return }
    prActionInFlight = true
    let resolver = statusResolver
    // Run `gh pr …` where the read probes run: in-place for git, but the colocated project root for
    // a jj workspace (gitless), else the action fails / targets the wrong repo context.
    let dir = WorkroomStatusResolver.ghProbeDirectory(
      path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
    Task { [weak self] in
      let r = await resolver.runPRCommand(action.arguments(number: number), in: dir)
      guard let self else { return }
      self.prActionInFlight = false
      if r.ok {
        // Re-probe to replace the optimistic state with GitHub's authoritative one.
        self.scheduleSelectedStatusRefresh()
      } else {
        // The command failed — undo the optimistic flip so the UI doesn't lie, then surface stderr.
        if var s = self.workroomStatuses[sid] {
          s.pr = priorPR
          self.workroomStatuses[sid] = s
        }
        self.errorTitle = "Couldn’t \(action.label.lowercased())"
        let stderr = r.stderr.trimmingCharacters(in: .whitespacesAndNewlines)
        self.errorMessage = stderr.isEmpty ? "The gh command failed." : stderr
      }
    }
  }

  /// Record a commit for `sid` and refresh what it changed.
  ///
  /// Unlike `performPRAction`, there is **no optimistic update**. A PR action flips a badge whose
  /// authority is remote and slow; a commit rewrites local state the panel reads directly, and
  /// pretending it succeeded would mean showing a clean file list for a commit a hook is still able
  /// to reject. The sheet shows progress instead, and the list changes only once it really has.
  ///
  /// `sid` is captured by the caller, never re-derived: `selectedTargetID` can move while a hook
  /// runs, and every refresh below must land on the row that actually changed.
  func performCommit(
    _ request: VCSCommitRequest, on sid: SidebarID,
    completion: @escaping (VCSCommitResult) -> Void
  ) {
    guard let item = selectedStatusWorkItem(for: sid) else {
      return completion(.failed(.other("That workroom is no longer available.")))
    }
    // Fixture mode swaps the WRITER — `FixtureVCSWriter` rather than spawning git or jj, since the
    // fixture paths aren't real repos and a live write would only ever fail. Only the writer: taking
    // an early return here instead skipped the whole store-side lane (the in-flight marks, the
    // captured-sid refresh), so the one tier that drives this code end to end exercised none of it.
    // `refreshStatus(for:)` already no-ops under the fixture, so the rest is safe to run.
    let root = item.projectRoot
    committingTargets.insert(sid)
    committingProjectRoots[root, default: 0] += 1
    Task { [weak self] in
      let result: VCSCommitResult
      if UITestFixture.isActive {
        result = await FixtureVCSWriter().commit(
          path: item.path, projectRoot: root, request: request)
      } else {
        do {
          let writer = try VCS.writer(for: URL(fileURLWithPath: item.path, isDirectory: true))
          result = await writer.commit(path: item.path, projectRoot: root, request: request)
        } catch {
          result = .failed(.other("\(error)"))
        }
      }
      guard let self else { return }
      self.committingTargets.remove(sid)
      // Decremented, never cleared: a sibling workroom of the same project can be committing too, and
      // dropping the key would re-open every read lane against a write still in progress.
      let remaining = (self.committingProjectRoots[root] ?? 1) - 1
      if remaining > 0 {
        self.committingProjectRoots[root] = remaining
      } else {
        self.committingProjectRoots.removeValue(forKey: root)
      }
      switch result {
      case .ok, .committedThenFailed:
        // Refresh by the CAPTURED sid. The Changes list is the load-bearing one for jj:
        // `handleWorkroomFileChange` deliberately drops bursts that touched only `.jj/`, so a jj
        // commit never self-refreshes from the watcher.
        self.refreshStatus(for: sid)
        // History gained a commit, and the ahead count and Push button both moved. Only refresh the
        // models that are still pointed at the row we committed — otherwise switching workrooms
        // mid-commit would repoint them at the wrong repo's log.
        if self.inspectorTargetID == sid {
          self.commitHistory.refresh()
          self.remoteState.refresh()
        }
      case .failed:
        break
      }
      completion(result)
    }
  }

  /// Ask which selected paths hold staged content a commit would discard, before committing.
  ///
  /// Read-only and ungated: it runs one `git status`, which takes no lock. Returns empty on any
  /// failure so a guard that cannot answer never blocks the commit — the guard exists to inform, and
  /// a broken guard must not become a broken commit.
  func stagedContentAtRisk(
    on sid: SidebarID, files: [ChangedFile], completion: @escaping ([String]) -> Void
  ) {
    guard !UITestFixture.isActive, let item = selectedStatusWorkItem(for: sid), item.vcs != "jj"
    else { return completion([]) }
    Task {
      guard let writer = try? VCS.writer(for: URL(fileURLWithPath: item.path, isDirectory: true))
      else { return completion([]) }
      completion(await writer.stagedContentAtRisk(path: item.path, files: files))
    }
  }

  /// Optimistically reflect a PR action in the in-memory status (no `gh`): the badge/state flip
  /// immediately on click, before the command returns. The real path restores the prior PR if `gh`
  /// fails and re-probes on success; fixture mode keeps this as the final result.
  private func applyOptimisticPRAction(_ action: PRAction, on sid: SidebarID) {
    guard var s = workroomStatuses[sid], let pr = s.pr else { return }
    let state: PullRequestInfo.State
    let draft: Bool
    switch action {
    case .markReady:
      state = .open
      draft = false
    case .convertToDraft:
      state = .open
      draft = true
    case .close:
      state = .closed
      draft = pr.isDraft
    case .reopen:
      state = .open
      draft = pr.isDraft
    }
    // Carry the prior mergeability forward (the re-probe corrects it): dropping it here would flip
    // `canMerge` off and blink the Merge button away for the (multi-second) round-trip.
    s.pr = PullRequestInfo(
      number: pr.number, title: pr.title, state: state, isDraft: draft, url: pr.url,
      reviewDecision: pr.reviewDecision, reviewers: pr.reviewers,
      mergeable: pr.mergeable, mergeState: pr.mergeState)
    workroomStatuses[sid] = s
  }

  /// Merge the selected workroom's PR (issue #88) with `method`: shell to `gh pr merge`, refresh on
  /// success, surface `stderr` on failure. Mirrors `performPRAction` — same in-flight gate, same
  /// `gh` repo context, same optimistic-then-authoritative flow — but the strategy is a parameter,
  /// so it's kept separate from the state-only `PRAction` verbs. In fixture mode it optimistically
  /// flips the PR to merged instead of spawning `gh`.
  func performMerge(_ method: PRMergeMethod, number: Int, on sid: SidebarID) {
    guard let item = selectedStatusWorkItem(for: sid) else { return }
    let priorPR = workroomStatuses[sid]?.pr
    applyOptimisticMerge(on: sid)
    if UITestFixture.isActive { return }
    prActionInFlight = true
    let resolver = statusResolver
    let dir = WorkroomStatusResolver.ghProbeDirectory(
      path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
    Task { [weak self] in
      let r = await resolver.runPRCommand(method.arguments(number: number), in: dir)
      guard let self else { return }
      self.prActionInFlight = false
      if r.ok {
        self.scheduleSelectedStatusRefresh()
      } else {
        if var s = self.workroomStatuses[sid] {
          s.pr = priorPR
          self.workroomStatuses[sid] = s
        }
        self.errorTitle = "Couldn’t merge pull request"
        let stderr = r.stderr.trimmingCharacters(in: .whitespacesAndNewlines)
        self.errorMessage = stderr.isEmpty ? "The gh command failed." : stderr
      }
    }
  }

  /// Optimistically flip the PR to merged (no `gh`): the badge turns purple and the Merge button
  /// disappears the instant the user confirms. `mergeable` is cleared so `canMerge` is false too.
  /// The real path restores the prior PR if `gh` fails and re-probes on success.
  private func applyOptimisticMerge(on sid: SidebarID) {
    guard var s = workroomStatuses[sid], let pr = s.pr else { return }
    s.pr = PullRequestInfo(
      number: pr.number, title: pr.title, state: .merged, isDraft: false, url: pr.url,
      reviewDecision: pr.reviewDecision, reviewers: pr.reviewers,
      mergeable: false, mergeState: pr.mergeState)
    workroomStatuses[sid] = s
  }

  /// Seed deterministic VCS status for the UI-test fixture targets so the Changes inspector is
  /// exercisable hermetically — the fixture paths aren't real repos, so the live probe would only
  /// ever report "unknown". No-ops outside fixture mode.
  func seedFixtureStatuses() {
    guard UITestFixture.isActive, let project = projects.first else { return }
    workroomStatuses[.root(project: project.path)] = UITestFixture.rootStatus
    if let workroom = project.workrooms.first {
      workroomStatuses[.workroom(project: project.path, name: workroom.name)] =
        UITestFixture.workroomStatus
    }
  }

  // MARK: - Internals

  /// Whether `sid` still maps to a live root/workroom. A status sweep captures its work-list up
  /// front, so a workroom can be deleted before its (slow) probe lands — without this guard the
  /// merge would write a ghost entry into `workroomStatuses` for a target that no longer exists.
  private func targetExists(_ sid: SidebarID) -> Bool {
    selectedStatusWorkItem(for: sid) != nil
  }

  /// `internal` rather than `private`: the commit sheet needs a row's path and vcs to open against it
  /// and to read `@`'s description for the prefill.
  func selectedStatusWorkItem(for sid: SidebarID) -> StatusWorkItem? {
    switch sid {
    case .root(let path):
      guard let p = projects.first(where: { $0.id == path }) else { return nil }
      return StatusWorkItem(sid: sid, path: p.path, vcs: p.vcs, projectRoot: p.path)
    case .workroom(let path, let name):
      guard let p = projects.first(where: { $0.id == path }),
        let w = p.workrooms.first(where: { $0.id == name })
      else { return nil }
      // `p.vcs` is the VCS type; `w.vcsName` is the branch name, not the type (see statusWorkItems).
      return StatusWorkItem(sid: sid, path: w.path, vcs: p.vcs, projectRoot: p.path)
    case .project:
      return nil
    }
  }

  /// Bounded fan-out: at most `cap` local probes in flight; refill as each completes. `cap` bounds
  /// cross-project parallelism and all git probes; it does NOT bound jj snapshots within one
  /// project — those additionally serialize behind each other through `WorkroomStatusResolver`'s
  /// `JJSnapshotGate` (keyed on `item.projectRoot`), since a project's workrooms share a backing
  /// repo a concurrent snapshot can contend on. Workrooms of *different* projects still run fully
  /// concurrently, up to `cap`.
  private func runLocalSweep(_ items: [StatusWorkItem], resolver: WorkroomStatusResolver, cap: Int)
    async
  {
    guard !items.isEmpty else { return }
    await withTaskGroup(of: (SidebarID, WorkroomStatus).self) { group in
      var idx = 0
      let initial = min(cap, items.count)
      while idx < initial {
        let item = items[idx]
        idx += 1
        group.addTask {
          (
            item.sid,
            await resolver.resolveLocal(
              path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
          )
        }
      }
      while let (sid, fresh) = await group.next() {
        if Task.isCancelled { break }
        mergeLocalStatus(fresh, into: sid)
        if idx < items.count {
          let item = items[idx]
          idx += 1
          group.addTask {
            (
              item.sid,
              await resolver.resolveLocal(
                path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
            )
          }
        }
      }
    }
  }

  private func runCISweep(_ items: [StatusWorkItem], resolver: WorkroomStatusResolver, cap: Int)
    async
  {
    guard !items.isEmpty else { return }
    // The CI rollup probe (#76) needs the repo's `owner/repo`. It's per-project, so resolve it once
    // per distinct project root and reuse it across that project's workrooms — not one `gh repo view`
    // per workroom. A project that can't resolve maps to `nil` (its workrooms then report CI absent).
    var nwoCache: [String: String?] = [:]
    for root in Set(items.map(\.projectRoot)) {
      if Task.isCancelled { return }
      nwoCache[root] = await resolver.resolveNameWithOwner(in: root)
    }
    await withTaskGroup(of: (SidebarID, CIResolution).self) { group in
      var idx = 0
      let initial = min(cap, items.count)
      while idx < initial {
        let item = items[idx]
        idx += 1
        let branch = workroomStatuses[item.sid]?.branchForCI
        let nwo = nwoCache[item.projectRoot] ?? nil
        group.addTask {
          (
            item.sid,
            await resolver.resolveCI(
              path: item.path, vcs: item.vcs, projectRoot: item.projectRoot, branch: branch,
              nameWithOwner: nwo)
          )
        }
      }
      while let (sid, res) = await group.next() {
        if Task.isCancelled { break }
        applyCIStatus(res, to: sid)
        if idx < items.count {
          let item = items[idx]
          idx += 1
          let branch = workroomStatuses[item.sid]?.branchForCI
          let nwo = nwoCache[item.projectRoot] ?? nil
          group.addTask {
            (
              item.sid,
              await resolver.resolveCI(
                path: item.path, vcs: item.vcs, projectRoot: item.projectRoot, branch: branch,
                nameWithOwner: nwo)
            )
          }
        }
      }
    }
  }

  /// Merge a fresh local result into the stored snapshot, preserving the (separately-resolved)
  /// CI fields so a local refresh never wipes the CI badge. Carries the jj working-copy change set
  /// through too — it comes from the same local probe as `dirty`, so dropping it here would leave
  /// the Changes panel on the git fallback even for a jj repo.
  func mergeLocalStatus(_ fresh: WorkroomStatus, into sid: SidebarID) {
    guard targetExists(sid) else { return }  // deleted mid-sweep → don't write a ghost entry
    var s = workroomStatuses[sid] ?? .unresolved
    s.dirty = fresh.dirty
    s.conflicted = fresh.conflicted
    s.changedFiles = fresh.changedFiles
    s.insertions = fresh.insertions
    s.deletions = fresh.deletions
    s.branchForCI = fresh.branchForCI
    s.jjWorkingCopy = fresh.jjWorkingCopy
    s.failure = fresh.failure
    s.lastChecked = Date()
    workroomStatuses[sid] = s
    // This sweep is the freshest evidence anyone has for these two, so it settles both of the caches
    // that would otherwise go on asserting a record-time answer: the branch name the toolbar
    // published, and the change kind an open diff tab captured when it opened.
    pruneResolvedBranchNameIfDrifted(sid, sweptBranch: fresh.branchForCI)
    refreshOpenDiffChangeKinds(for: sid, status: s)
  }

  /// Drop the toolbar's cached branch name for `sid` when this sweep disagrees with it.
  ///
  /// `resolvedBranchNames` leads `branchName(for:)` because it is normally the freshest source — but it
  /// is written only for the focused target, and only while the inspector is showing Changes
  /// (`focusRemoteStateIfShown`). So `git switch` in a workroom's terminal left every branch-showing
  /// surface on the old name indefinitely: nothing invalidated source #1, and the sweep that DID know
  /// better sat behind it. A disagreement means the cache is no longer the freshest answer, so it
  /// yields rather than wins — and the next toolbar read republishes it.
  ///
  /// Only a non-empty swept branch counts: git reports none for a detached HEAD, and jj none for an
  /// unbookmarked `@` — neither is evidence the cached name is wrong.
  private func pruneResolvedBranchNameIfDrifted(_ sid: SidebarID, sweptBranch: String?) {
    guard let cached = resolvedBranchNames[sid], let swept = sweptBranch, !swept.isEmpty,
      cached != swept
    else { return }
    setResolvedBranchName(nil, for: sid)
  }

  private func applyCIStatus(_ res: CIResolution, to sid: SidebarID) {
    guard var s = workroomStatuses[sid] else { return }
    switch res {
    case .state(let x):
      s.ci = x
      s.ciCheckedAt = Date()
    case .absent:
      s.ci = nil
      s.ciCheckedAt = Date()
    case .keepPrior:
      // Transient rate-limit / network blip. Stamp `ciCheckedAt` so the TTL throttles re-probes —
      // but ONLY if we've probed before (ciCheckedAt set). On a first-ever probe that blips, leave
      // it nil so the next sweep retries instead of hiding CI for the full TTL on one blip. Coarse
      // but cheap; true exponential backoff is a future refinement.
      if s.ciCheckedAt != nil { s.ciCheckedAt = Date() }
    }
    workroomStatuses[sid] = s
  }

  // Internal (not `private`) so `@testable` can drive the checks lifecycle (clear-on-PR-change /
  // clear-on-no-PR, issue #75) directly.
  func applyPRStatus(_ res: PRResolution, to sid: SidebarID) {
    guard var s = workroomStatuses[sid] else { return }
    switch res {
    case .info(let pr):
      // Checks are keyed to a PR's identity (issue #75). If the PR changed (different number), the
      // old PR's checks are stale — drop them so they can't render under the new PR until
      // `resolveChecks` refills them. Same number ⇒ keep them (e.g. the raw→enriched re-apply).
      if s.pr?.number != pr.number {
        s.checks = nil
        s.checksCheckedAt = nil
      }
      s.pr = pr
      s.prCheckedAt = Date()
    case .absent:
      // No PR ⇒ `resolveChecks` won't run, so the checks must be cleared here (not only in
      // `applyChecksStatus`) or a disappearing PR would leave its checks rendered.
      s.pr = nil
      s.checks = nil
      s.checksCheckedAt = nil
      s.prCheckedAt = Date()
    case .keepPrior:
      // Transient blip: keep the last good PR. Stamp `prCheckedAt` so the TTL throttles re-probes,
      // but only if we've probed before — a first-ever blip leaves it nil so the next sweep retries.
      if s.prCheckedAt != nil { s.prCheckedAt = Date() }
    }
    workroomStatuses[sid] = s
  }

  /// Apply a PR-checks probe result (issue #75). `.list` (including `[]` for "loaded, no checks")
  /// sets the rows and stamps `checksCheckedAt`. `.absent` (no checks reported / gh error) is *also*
  /// a loaded state — it stamps with an empty list, distinct from the not-loaded `nil`, so the panel
  /// stops falling back to the run-list aggregate. `.keepPrior` (transient blip) keeps the last good
  /// list, stamping only if we've probed before (so a first-ever blip retries next time). Internal
  /// (not `private`) so `@testable` reaches it. The clear-on-no-PR / clear-on-PR-change paths live in
  /// `applyPRStatus` — `resolveChecks` never runs without a PR.
  func applyChecksStatus(_ res: ChecksResolution, to sid: SidebarID) {
    guard var s = workroomStatuses[sid] else { return }
    switch res {
    case .list(let checks):
      s.checks = checks
      s.checksCheckedAt = Date()
    case .absent:
      s.checks = []
      s.checksCheckedAt = Date()
    case .keepPrior:
      if s.checksCheckedAt != nil { s.checksCheckedAt = Date() }
    }
    workroomStatuses[sid] = s
  }

  // MARK: - Live filesystem watch (selected workroom)

  /// Whether `sid` is a workroom whose create/setup is still in flight (issue: create-time FSEvents
  /// storm). While a setup script writes the worktree (e.g. `npm install`), arming the recursive
  /// FSEvents watcher on it or probing its VCS status is pointless churn — the tree isn't settled and
  /// FSEvents floods ~70 callbacks/sec under that load. `creatingWorkrooms` (set as setup begins,
  /// cleared when it finishes) is the exact signal; this is the single conversion point from the
  /// `SidebarID`-keyed status world to the `TerminalTarget.ID`-keyed `creatingWorkrooms` set. Roots
  /// and projects are never "creating".
  func isCreating(_ sid: SidebarID) -> Bool {
    guard case .workroom(let project, let name) = sid else { return false }
    return creatingWorkrooms.contains(TerminalTarget.workroomID(project: project, name: name))
  }

  /// Whether a commit is running for this row. Suppresses the same three lanes `isCreating` does, for
  /// a closely-related reason.
  ///
  /// Necessary because `JJSnapshotGate` is not sufficient on its own here: its `maxChainWait` is 30s
  /// and a commit's timeout is far longer (a `pre-commit` hook that runs a test suite is ordinary), so
  /// a queued status probe would hit the gate's documented self-heal and run **concurrently with the
  /// commit** — snapshotting `@` mid-write for jj, contending on `index.lock` for git. Suppressing the
  /// lanes is the fix; raising the ceiling would only make every other lane wait longer.
  ///
  /// It also stops the panel rendering a half-staged tree: `git commit` moves the index and refs as it
  /// goes, and `GitProvider.workingStatus` collapses index and worktree deltas into one row, so a
  /// probe landing mid-commit shows a state that never really existed.
  func isCommitting(_ sid: SidebarID) -> Bool { committingTargets.contains(sid) }

  /// Whether ANY workroom of this project has a commit in flight.
  ///
  /// The question every read lane has to ask, rather than `isCommitting(sid)`. `JJSnapshotGate`
  /// serializes on the project root, and its `maxChainWait` self-heal (30s) is far shorter than
  /// `commitTimeout` (600s) — so a probe queued behind a slow hook stops waiting and runs anyway.
  /// Suppression is what actually keeps these lanes off a repo mid-write; the gate alone does not.
  func isCommittingProject(_ projectRoot: String) -> Bool {
    committingProjectRoots[projectRoot, default: 0] > 0
  }

  /// Re-probe ONE row's local status, named explicitly.
  ///
  /// `scheduleSelectedStatusRefresh` cannot serve a commit: it derives its target from the LIVE
  /// `selectedTargetID`, so switching workrooms while a commit is in flight would commit A and
  /// refresh B — leaving the row that actually changed stale and re-probing one that didn't. Every
  /// post-commit refresh therefore names the sid it captured when the sheet opened.
  func refreshStatus(for sid: SidebarID) {
    guard !UITestFixture.isActive, let item = selectedStatusWorkItem(for: sid) else { return }
    let resolver = statusResolver
    Task { [weak self] in
      let fresh = await resolver.resolveLocal(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
      guard let self, self.targetExists(sid) else { return }
      self.mergeLocalStatus(fresh, into: sid)
    }
  }

  /// Point the filesystem watcher at the selected workroom's directory, or stop it when nothing
  /// statusable is selected — or when the selection's create is still in flight (don't watch a tree a
  /// setup script is actively writing). No-ops in fixture mode (the seeded status must stay
  /// deterministic).
  func updateSelectedWorkroomWatch() {
    guard !UITestFixture.isActive, let sid = selectedTargetID, !isCreating(sid),
      let item = selectedStatusWorkItem(for: sid)
    else {
      workroomFileWatcher.stop()
      return
    }
    workroomFileWatcher.start(path: item.path)
  }

  /// React to a filesystem change under the selected workroom: re-probe its *local* status only
  /// (dirty/ahead-behind/changed-files/jj head) and merge. CI/PR stay on their TTLs — a file save
  /// shouldn't fire a `gh` call. Cancel-and-replace so the latest change wins and at most one probe
  /// from THIS lane runs at a time — it does NOT by itself prevent this probe's jj snapshot from
  /// overlapping the sweep's or the selection-refresh's for the same project; that cross-lane
  /// ordering is `JJSnapshotGate`'s job (via `WorkroomStatusResolver.resolveLocal`).
  func handleWorkroomFileChange(_ paths: [String]) {
    guard !UITestFixture.isActive, let sid = selectedTargetID,
      let item = selectedStatusWorkItem(for: sid)
    else { return }
    // Defensive: never probe a mid-setup worktree. The watcher shouldn't be armed while creating
    // (updateSelectedWorkroomWatch stops it), but a stray in-flight FSEvents callback can land during
    // the stop transition — bail so it can't fork a probe against the tree the setup script is writing.
    if isCreating(sid) { return }
    // Same for a commit in flight, keyed by project root — a git worktree's index lives in the main
    // repo, so a sibling workroom's commit churns the very files this probe reads. This lane is the
    // one that would fire MOST during a git commit: the `.jj/` filter below saves jj from
    // self-triggering, but git's own index and ref churn is deliberately let through as real signal,
    // so `git add`/`git commit` would each fork a probe against a tree mid-write.
    if isCommittingProject(item.projectRoot) { return }
    // A jj *local* probe snapshots `@` (writes under `.jj/`), which would itself trip the watcher —
    // an endless refresh loop. So ignore a burst that touched ONLY jj-internal paths. (git probes are
    // read-only, and `.git/index` changes from `git add` are real signal, so git events pass through.)
    if item.vcs == "jj", !paths.isEmpty, paths.allSatisfy(Self.isJJInternalPath) { return }
    let resolver = statusResolver
    watchRefreshTask?.cancel()
    watchRefreshTask = Task { [weak self] in
      let fresh = await resolver.resolveLocal(
        path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
      guard let self, !Task.isCancelled, self.selectedTargetID == sid else { return }
      self.mergeLocalStatus(fresh, into: sid)
    }
  }

  /// Whether an FSEvents path is inside a jj internal dir (a `.jj` path component) — used to skip the
  /// snapshot self-trigger. Component-based so it doesn't match a working file merely named `.jj…`.
  /// `nonisolated` (pure) so it's callable off the main actor.
  nonisolated static func isJJInternalPath(_ path: String) -> Bool {
    path.split(separator: "/").contains(".jj")
  }
}

import Foundation

/// The full result of a short status command: stdout, stderr, exit code, and whether the
/// timeout fired. Unlike `CommandRunning` (which collapses everything to `String?`), this
/// keeps the exit code and timeout flag so `WorkroomStatusResolver` can tell "not a repo"
/// (git exit 128) from "gh not installed" (exit 127) from "timed out" from "clean" — the
/// distinctions the status UI's unknown/stale/absent matrix depends on.
struct CommandResult: Sendable, Equatable {
  let stdout: String
  let stderr: String
  let exitCode: Int32
  let timedOut: Bool
  /// The child was killed by a signal (`terminationReason == .uncaughtSignal`) rather than exiting
  /// normally — our own cancellation SIGKILL, our timeout's SIGTERM, an OS kill under memory
  /// pressure, a crash, or a signal delivered around sleep/wake. `exitCode` is then the **signal
  /// number** (SIGKILL = 9, SIGTERM = 15), NOT a CLI exit status, so no classifier may read it as
  /// one: `gh` "exited 9" is not a logout, and `git` "exited 15" is not a push failure.
  ///
  /// `WorkroomCLI.CLIResult` has carried this exact field since `a64e4269` ("stop 'exited with code
  /// 15' dialog on wake from sleep"); this is the same fact for the runner that *deliberately*
  /// SIGKILLs on cancellation.
  ///
  /// **`timedOut` implies `signaled`.** The timeout path marks `timedOut` and then calls
  /// `terminate()` (SIGTERM), so a timed-out child sets BOTH. Every consumer must therefore test
  /// `timedOut` first, or a timeout gets misreported as a bare interruption.
  let signaled: Bool

  /// `/usr/bin/env` exits 127 when the command (git/jj/gh) isn't on PATH.
  static let commandNotFound: Int32 = 127
  /// git exits 128 for "not a git repository" and similar fatal usage errors.
  static let gitFatal: Int32 = 128

  /// Written out rather than synthesized: a `let` with an initial value is EXCLUDED from the
  /// memberwise init entirely, so `let signaled = false` would compile at all ~60 construction
  /// sites and then fail only where the runner tries to set it. Defaulted last so those sites —
  /// almost all tests, none of which care about signals — keep compiling untouched.
  init(stdout: String, stderr: String, exitCode: Int32, timedOut: Bool, signaled: Bool = false) {
    self.stdout = stdout
    self.stderr = stderr
    self.exitCode = exitCode
    self.timedOut = timedOut
    self.signaled = signaled
  }

  var ok: Bool { exitCode == 0 && !timedOut }
}

/// A seam (mirrors `CommandRunning`) so `WorkroomStatusResolver` is unit-testable without
/// spawning real git/jj/gh — but typed (`CommandResult`, not `String?`).
protocol StatusCommandRunning: Sendable {
  func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
    async -> CommandResult

  /// Like `run`, but feeds `stdin` to the child on its standard input.
  ///
  /// Exists for the commit path, where passing data as **argv is either unsafe or impossible**:
  /// - `git add --pathspec-from-file=- --pathspec-file-nul` takes the selected paths NUL-separated
  ///   on stdin. That is the only form git treats pathspecs as **literal** — after a bare `--` they
  ///   are still glob magic, so selecting `a[b].txt` also stages `ab.txt` (measured), and a file
  ///   named `*` stages the whole tree. It also sidesteps `E2BIG`, which a few thousand long paths
  ///   in `proc.arguments` would hit at spawn, before git can emit anything classifiable.
  /// - `git commit --file=-` takes the message on stdin, so no length or encoding question arises.
  ///
  /// A per-call **environment** override is deliberately NOT added yet: its only planned consumer is
  /// `GIT_INDEX_FILE` for temp-index commits, which is deferred, and an unused parameter is surface
  /// nobody can test.
  func run(
    _ executable: String, _ args: [String], in directory: String, timeout: TimeInterval,
    stdin: Data?
  ) async -> CommandResult

  /// Like `run`, but for a command that will touch the **network** and therefore may want to
  /// authenticate — `git fetch/push/pull`, `jj git fetch/push`.
  ///
  /// A read like `git status` can never prompt, so it wants the minimal, predictable environment
  /// `run` gives it. A push can: it may need an SSH agent the GUI environment can't see, and it may
  /// try to ask for a passphrase or a host-key confirmation with nowhere to ask. See
  /// `StatusCommandRunner.networkEnvironment` for what changes and why.
  func runNetwork(
    _ executable: String, _ args: [String], in directory: String,
    timeout: TimeInterval
  ) async -> CommandResult
}

extension StatusCommandRunning {
  /// Test doubles never reach a real network, so the distinction is meaningless for them — forward
  /// and let them stay two-line stubs. Only `StatusCommandRunner` overrides this.
  func runNetwork(
    _ executable: String, _ args: [String], in directory: String,
    timeout: TimeInterval
  ) async -> CommandResult {
    await run(executable, args, in: directory, timeout: timeout)
  }

  /// Same reasoning as `runNetwork`: a double that records argv doesn't care about the payload, so
  /// it stays a two-line stub. A double that DOES need to assert on stdin (the commit tests) can
  /// override this one method. Only `StatusCommandRunner` writes a real pipe.
  func run(
    _ executable: String, _ args: [String], in directory: String, timeout: TimeInterval,
    stdin: Data?
  ) async -> CommandResult {
    await run(executable, args, in: directory, timeout: timeout)
  }
}

/// Default `StatusCommandRunning`: spawns via `/usr/bin/env` (augmented PATH finds Homebrew
/// git/jj/gh), git locks/prompt disabled, and enforces `timeout` by terminating the process.
///
/// Unlike `ProcessCommandRunner` (which reads stdout *in* the termination handler — safe only
/// because a branch name is tiny), this drains stdout AND stderr **concurrently on background
/// queues while the process runs** (the `WorkroomCLI` pattern). Status output can be large (a
/// repo with thousands of changed files, a big `gh` JSON payload); reading post-termination
/// would let the OS pipe buffer fill, block the child on write, and deadlock until the timeout.
/// Retained output is capped (`maxBytes`) so a pathological repo can't blow memory — the reader
/// keeps draining past the cap (so the child never blocks) but discards the overflow.
struct StatusCommandRunner: StatusCommandRunning, Sendable {
  var maxBytes: Int = 4 * 1024 * 1024

  /// Auth-relevant variables forwarded from the user's shell for network commands only.
  ///
  /// A Finder- or Dock-launched `.app` inherits launchd's environment, not the user's shell, and this
  /// runner otherwise overrides only PATH. That was harmless while it ran `git status` and `gh` (which
  /// carries its own token), but it breaks authentication outright: `SSH_AUTH_SOCK` is how a process
  /// finds an SSH agent, and for anyone using 1Password's agent, gpg-agent, or a custom socket it is
  /// set in `.zshrc` and nowhere else. Without it their `git push` cannot reach the agent, and the
  /// error would tell them to configure a credential helper they already have.
  ///
  /// Deliberately an allowlist, not the whole probed environment (which `ShellEnvironment.environment()`
  /// hands to setup/teardown scripts): network ops now run automatically on inspector focus, and a
  /// wholesale transplant would put every variable in the user's shell — secrets included — into a
  /// child on an automatic path.
  static let forwardedAuthKeys = [
    "SSH_AUTH_SOCK", "SSH_AGENT_PID", "GIT_SSH_COMMAND", "GIT_CONFIG_GLOBAL", "XDG_CONFIG_HOME",
  ]

  /// Variables removed for network commands so `ssh` cannot find a graphical prompt helper.
  static let networkClearedKeys = ["SSH_ASKPASS", "DISPLAY"]

  /// The environment for a network command: `base` plus forwarded auth vars, with ssh pinned to
  /// fail fast instead of asking a human.
  ///
  /// `GIT_TERMINAL_PROMPT=0` (set by `run`) governs **git's own** credential prompts and says nothing
  /// to `ssh`. So an SSH remote with a passphrase-protected key and no agent, or a host whose key
  /// isn't in `known_hosts`, would otherwise stall until the timeout — 120s for fetch/push, 300s for
  /// pull. `BatchMode=yes` turns both into an immediate, classifiable failure, and
  /// `SSH_ASKPASS_REQUIRE=never` stops ssh reaching for a GUI helper (OpenSSH 8.4+; macOS ships 10.x).
  ///
  /// A user's own `GIT_SSH_COMMAND` is preserved and appended to rather than replaced — it commonly
  /// carries `-i <key>` or a proxy command that must survive.
  ///
  /// Pure and static so the whole policy is unit-testable without spawning anything.
  static func networkEnvironment(base: [String: String], probed: [String: String])
    -> [String: String]
  {
    var env = base
    for key in forwardedAuthKeys {
      // The inherited environment wins: if it's already set, the app was launched from a shell that
      // had it, and that value is at least as current as the probe's.
      if env[key] == nil, let value = probed[key], !value.isEmpty { env[key] = value }
    }
    for key in networkClearedKeys { env.removeValue(forKey: key) }
    let ssh = env["GIT_SSH_COMMAND"]?.trimmingCharacters(in: .whitespacesAndNewlines)
    env["GIT_SSH_COMMAND"] = (ssh?.isEmpty == false ? ssh! : "ssh") + " -o BatchMode=yes"
    env["SSH_ASKPASS_REQUIRE"] = "never"
    return env
  }

  func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
    async -> CommandResult
  {
    await run(executable, args, in: directory, timeout: timeout, network: false, stdin: nil)
  }

  func run(
    _ executable: String, _ args: [String], in directory: String, timeout: TimeInterval,
    stdin: Data?
  ) async -> CommandResult {
    await run(executable, args, in: directory, timeout: timeout, network: false, stdin: stdin)
  }

  func runNetwork(
    _ executable: String, _ args: [String], in directory: String,
    timeout: TimeInterval
  ) async -> CommandResult {
    await run(executable, args, in: directory, timeout: timeout, network: true, stdin: nil)
  }

  private func run(
    _ executable: String, _ args: [String], in directory: String,
    timeout: TimeInterval, network: Bool, stdin: Data?
  ) async -> CommandResult {
    let proc = Process()
    proc.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    proc.arguments = [executable] + args
    proc.currentDirectoryURL = URL(fileURLWithPath: directory)

    var env = ProcessInfo.processInfo.environment
    env["PATH"] = ShellEnvironment.path()
    env["GIT_OPTIONAL_LOCKS"] = "0"
    env["GIT_TERMINAL_PROMPT"] = "0"
    // Pin the message locale: EVERY consumer of this runner classifies failures by matching English
    // substrings of git's stderr (`CLIVCSWriter.classify`, `WorkroomStatusResolver`), and git ships
    // translated message catalogs. Homebrew git 2.55 under a French locale answers
    // `erreur : le spécificateur de chemin …`, so without this a non-English user loses the ENTIRE
    // failure taxonomy at once — auth, host-key, rejected-push, dirty-tree and leftover-lock all
    // collapse to `.other(rawStderr)` with no recovery offered.
    //
    // `LC_ALL`, not `LC_MESSAGES`: this env is seeded from `ProcessInfo.environment`, so the user's own
    // `LC_ALL` may be inherited, and it OUTRANKS `LC_MESSAGES` — setting the narrower variable is
    // silently defeated (measured: `LC_ALL=fr_FR.UTF-8 LC_MESSAGES=C git …` still answers in French).
    //
    // Safe for paths despite forcing the C charset: git writes pathnames as raw bytes (and quotes
    // non-ASCII per `core.quotePath` regardless of locale), so `LC_ALL=C` renders a `café-ünï.txt`
    // byte-identically to the user's own locale — verified, not assumed. jj and gh are unaffected
    // either way; neither localizes.
    env["LC_ALL"] = "C"
    // A workroom can be a clone of an *untrusted* repo, and the status sweep runs git automatically
    // on load/focus/selection. `git diff` would otherwise run an inherited external-diff program;
    // unset it so only the explicit `--no-ext-diff` flag (see WorkroomStatusResolver) governs diffs.
    env.removeValue(forKey: "GIT_EXTERNAL_DIFF")
    if network { env = Self.networkEnvironment(base: env, probed: ShellEnvironment.environment()) }
    proc.environment = env

    let outPipe = Pipe()
    let errPipe = Pipe()
    proc.standardOutput = outPipe
    proc.standardError = errPipe
    // Never let a child read the app's stdin. Unset, it INHERITS ours — which under `make app-run`
    // (or `Scripts/run.sh`) is a real terminal, so a prompting `ssh` or `git` could sit waiting on a
    // tty that the same binary won't have when launched from Finder. Pinning it makes the two launch
    // contexts behave identically and turns any prompt into an immediate EOF. `ShellEnvironment.probe`
    // already does this for the same reason.
    //
    // A caller-supplied payload replaces the null device with a pipe we write and then close, so the
    // child still sees a clean EOF and can never wait on a human.
    let inPipe: Pipe? = stdin == nil ? nil : Pipe()
    proc.standardInput = inPipe ?? FileHandle.nullDevice

    // `proc` is shared with the @Sendable cancellation handler; box it so the non-Sendable Process
    // can cross that boundary (mirrors the @unchecked Sendable helpers below).
    let box = ProcessBox(proc)

    return await withTaskCancellationHandler {
      await withCheckedContinuation { (continuation: CheckedContinuation<CommandResult, Never>) in
        let state = StatusRunState()
        let drain = DispatchGroup()
        let cap = maxBytes
        let gate = CommandResumeGate(continuation)

        // Concurrent drains (the deadlock fix). availableData blocks until data or EOF;
        // started before run() so we never miss a fast child's output, harmless until it runs.
        drain.enter()
        DispatchQueue.global().async {
          state.setStdout(Self.readCapped(outPipe.fileHandleForReading, cap: cap))
          drain.leave()
        }
        drain.enter()
        DispatchQueue.global().async {
          state.setStderr(Self.readCapped(errPipe.fileHandleForReading, cap: cap))
          drain.leave()
        }

        let timeoutItem = DispatchWorkItem {
          state.markTimedOut()
          if proc.isRunning { proc.terminate() }  // SIGTERM
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + timeout, execute: timeoutItem)

        // Hard-kill fallback: a wedged child (e.g. `gh` blocked on a dead socket) can ignore SIGTERM,
        // so `terminationHandler` — the only place the continuation resumes — would never fire and the
        // awaiting Task would hang forever, defeating the timeout. SIGKILL is uncatchable, guaranteeing
        // the process exits and we resume. A 2s grace after SIGTERM lets well-behaved children exit.
        let killItem = DispatchWorkItem {
          if proc.isRunning { ProcessTree.killTree(proc.processIdentifier) }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + timeout + 2, execute: killItem)

        proc.terminationHandler = { finished in
          timeoutItem.cancel()
          killItem.cancel()
          // The process has exited, so its own pipe write ends are closed and EOF is imminent. But a
          // grandchild that inherited the pipe (a helper spawned by gh/git) can hold the write end
          // open after the parent dies — an unbounded `drain.wait()` would then never return and the
          // continuation would never resume, wedging this probe slot forever. Bound the wait and
          // resume with whatever drained; a still-blocked reader writes to `state` we no longer read
          // (safe — lock-guarded) and exits when the grandchild finally closes the pipe.
          _ = drain.wait(timeout: .now() + 2)
          gate.resume(
            CommandResult(
              stdout: String(decoding: state.stdout, as: UTF8.self),
              stderr: String(decoding: state.stderr, as: UTF8.self),
              exitCode: finished.terminationStatus,
              timedOut: state.timedOut,
              // A killed child reports its SIGNAL in `terminationStatus`, so record which kind of
              // exit this was — otherwise a cancelled/killed probe is indistinguishable from a CLI
              // that ran and failed, which is how a SIGKILLed `gh auth status` came to be read as
              // "not signed in" and a SIGTERMed `git push` as "git exited 15".
              signaled: finished.terminationReason == .uncaughtSignal))
        }

        do {
          try proc.run()
          // Feed stdin AFTER the child exists, on a background queue, and close to signal EOF.
          // Off the calling thread because a payload larger than the 64K pipe buffer blocks until
          // the child drains it, and `git` does not start reading until it has parsed its argv.
          if let inPipe, let payload = stdin {
            DispatchQueue.global().async {
              let handle = inPipe.fileHandleForWriting
              // Darwin's per-descriptor SIGPIPE suppression. Without it, a child that exits before
              // reading (git rejecting its argv, a hook killing it) makes our `write(2)` raise
              // SIGPIPE, whose default disposition TERMINATES the app — a crash reachable from an
              // ordinary failed commit. With it the write just returns EPIPE, which `try?` drops.
              _ = fcntl(handle.fileDescriptor, F_SETNOSIGPIPE, 1)
              if !payload.isEmpty { try? handle.write(contentsOf: payload) }
              try? handle.close()
            }
          }
        } catch {
          // Launch failed (e.g. cwd vanished). Close the write ends so the drain readers hit
          // EOF instead of blocking forever, then resolve as command-not-found.
          timeoutItem.cancel()
          killItem.cancel()
          try? inPipe?.fileHandleForWriting.close()
          try? outPipe.fileHandleForWriting.close()
          try? errPipe.fileHandleForWriting.close()
          gate.resume(
            CommandResult(
              stdout: "", stderr: "\(error)", exitCode: CommandResult.commandNotFound,
              timedOut: false))
        }
      }
    } onCancel: {
      // The awaiting Task was cancelled (e.g. a superseded sweep, or rapid selection cycling). Kill
      // the in-flight child so a cancelled probe doesn't leave a git/jj/gh process running to its own
      // timeout. terminationHandler then resumes the continuation with the abandoned result, which
      // the cancelled caller discards. SIGKILL (not SIGTERM) so a wedged child dies promptly.
      box.terminate()
    }
  }

  /// Drain a pipe to EOF, retaining at most `cap` bytes but reading the rest so the child
  /// never blocks on a full pipe buffer.
  private static func readCapped(_ handle: FileHandle, cap: Int) -> Data {
    var collected = Data()
    while true {
      // `read(upToCount:)` (throwing) instead of `availableData`: the latter raises an
      // *Objective-C* `NSFileHandleOperationException` on a read error (common right after the
      // child is `terminate()`d out from under the open read end), which Swift can't catch — it
      // crashes the app. Treat a read error as EOF and return what we have.
      let chunk: Data
      do { chunk = try handle.read(upToCount: 1 << 16) ?? Data() } catch { break }
      if chunk.isEmpty { break }  // EOF: pipe closed
      if collected.count < cap {
        collected.append(chunk.prefix(cap - collected.count))
      }
    }
    return collected
  }
}

/// Boxes a non-Sendable `Process` so it can be captured by the @Sendable task-cancellation handler.
private final class ProcessBox: @unchecked Sendable {
  private let process: Process
  init(_ process: Process) { self.process = process }
  /// SIGKILL the child (and any descendants it spawned) if still running — the cancellation path
  /// abandons the result, so kill promptly rather than wait out a SIGTERM grace.
  ///
  /// Hopped to a global queue because `withTaskCancellationHandler`'s `onCancel` runs **synchronously
  /// on whichever thread called `cancel()`**, and the hottest canceller is the main thread:
  /// `selectedTargetID.didSet` → `scheduleSelectedStatusRefresh` → `selectionStatusTask?.cancel()`
  /// supersedes the in-flight probe on *every* selection change. `ProcessTree.killTree` walks the tree
  /// by spawning a `pgrep -P` per node and blocking on `waitUntilExit` for each, so inline it stalled
  /// the main thread for the length of that walk while switching workroom tabs — and a blocking wait
  /// spins a nested run loop, which drains queued main-queue blocks at a point SwiftUI hasn't committed
  /// its update yet (that reordering is what surfaced the split-member selection snap-back). Deferring
  /// the kill costs nothing: the continuation resumes from `terminationHandler`, never from here, and
  /// the cancelled caller discards the result. Matches `killItem`, which already kills off a global
  /// queue.
  func terminate() {
    let process = self.process
    DispatchQueue.global(qos: .userInitiated).async {
      if process.isRunning { ProcessTree.killTree(process.processIdentifier) }
    }
  }
}

/// Mutable scratch shared between the drain queues and the termination handler. Locked
/// because the two reads and the handler touch it from different threads.
private final class StatusRunState: @unchecked Sendable {
  private let lock = NSLock()
  private var _stdout = Data()
  private var _stderr = Data()
  private var _timedOut = false

  func setStdout(_ d: Data) {
    lock.lock()
    _stdout = d
    lock.unlock()
  }
  func setStderr(_ d: Data) {
    lock.lock()
    _stderr = d
    lock.unlock()
  }
  func markTimedOut() {
    lock.lock()
    _timedOut = true
    lock.unlock()
  }

  var stdout: Data {
    lock.lock()
    defer { lock.unlock() }
    return _stdout
  }
  var stderr: Data {
    lock.lock()
    defer { lock.unlock() }
    return _stderr
  }
  var timedOut: Bool {
    lock.lock()
    defer { lock.unlock() }
    return _timedOut
  }
}

/// Resumes a `CommandResult` continuation exactly once (termination vs launch-failure race).
private final class CommandResumeGate: @unchecked Sendable {
  private let lock = NSLock()
  private var done = false
  private let continuation: CheckedContinuation<CommandResult, Never>

  init(_ continuation: CheckedContinuation<CommandResult, Never>) {
    self.continuation = continuation
  }

  func resume(_ value: CommandResult) {
    lock.lock()
    let first = !done
    done = true
    lock.unlock()
    if first { continuation.resume(returning: value) }
  }
}

  return branchName
}

/// Run a mutating `gh pr …` command (Phase 2b PR actions). Network timeout, like the read probes.
/// Returns the raw result so the caller can refresh on success or surface `stderr` on failure.
func runPRCommand(_ arguments: [String], in dir: String) async -> CommandResult {
  await runner.run("gh", arguments, in: dir, timeout: ciTimeout)
}

/// Probe whether `gh` is installed and authenticated (machine-global, not per-workroom). Runs
/// `gh auth status --active --json hosts` in a neutral dir; a network/keyring blip reports
/// `available` so a flaky connection doesn't raise a false "not signed in" warning.
///
/// `--active` (gh ≥ 2.57.0) scopes the check to the *active* account on each host — the one
/// `gh pr list` / `gh run list` actually use. Without it, plain `gh auth status` exits non-zero
/// when *any* account on *any* host has an issue, so a single broken secondary / GitHub-App
/// account would flip the whole app to "not signed in" and gate off the CI/PR sweep even though
/// the active account works fine (issue #50).
///
/// `--json hosts` (issue #86) is the fix for the *flapping* warning. `gh auth status` validates
/// the token over the network; when api.github.com is briefly unreachable it can't tell "couldn't
/// reach the API" from "token is bad", so the plain-text form misreports the blip as "token
/// invalid" and exits non-zero — a false "not signed in". The `--json` form instead always exits
/// zero (barring a fatal error) and emits a per-account `state`/`error`, so we can tell a
/// transport failure (transient → don't cry wolf) from a genuine 401 (really logged out).
///
/// Measured against gh 2.97.0: the JSON goes to **stdout** and the exit code is **0** in every
/// genuine state — signed in, token rejected (a 401 in the per-account `error`), and no config at
/// all (`{"hosts":{}}`). So a non-zero exit means we learned nothing, not that you're logged out.
func resolveGitHubCLI() async -> GHAuthProbe {
  let r = await runner.run(
    "gh", ["auth", "status", "--active", "--json", "hosts"], in: NSTemporaryDirectory(),
    timeout: ciTimeout)
  return Self.classifyGitHubCLI(r)
}

// MARK: - Pure parsers / classifiers (unit-tested directly)

/// The outcome of one `gh auth status` probe: either a verdict about the machine, or "the probe
/// told us nothing" — which is a THIRD thing, not a synonym for "gh works".
///
/// Forcing "no news" into a `GitHubCLIStatus` is what made the old timeout path lie: reporting
/// `.available` for a probe that never answered doesn't just fail to warn, it actively ERASES a
/// correct `.notAuthenticated`/`.notInstalled`/`.tooOld` and leaves the user with a silent panel
/// and PR probes that fail for no visible reason. `.keepPrior` mirrors `GHPreflight.keepPrior` and
/// `CIResolution.keepPrior`, and — critically — the store does not stamp the TTL for it, so the
/// next lane re-probes instead of trusting a non-answer for a full minute.
enum GHAuthProbe: Equatable {
  case verdict(GitHubCLIStatus)
  case keepPrior
}

/// Classify one `gh auth status --active --json hosts` result.
///
/// ```
///   exit 127 ─────────────────────────► .verdict(.notInstalled)
///   timedOut ─────────────────────────► .keepPrior      ◄─ MUST precede `signaled`:
///        │                                                 the timeout SIGTERMs the child,
///        │                                                 so a timeout sets BOTH flags
///   parseable JSON ───────────────────► .verdict(from the payload)
///        │                              ◄─ BEFORE `signaled`: a child that emitted a COMPLETE
///        │                                 401 and was killed afterwards really did tell us
///        │                                 the token is bad. Don't discard evidence.
///   signaled (no parseable payload) ──► .keepPrior      ◄─ killed/crashed: no verdict, no news
///        │
///   exit 0 ───────────────────────────► .verdict(.available)
///   non-zero ─────────────────────────► .verdict(.notAuthenticated)
/// ```
static func classifyGitHubCLI(_ r: CommandResult) -> GHAuthProbe {
  if r.exitCode == CommandResult.commandNotFound { return .verdict(.notInstalled) }
  if r.timedOut { return .keepPrior }  // network/keyring blip — and always also `signaled`
  // `--json hosts` exits 0 even when the active token fails to validate, emitting structured
  // per-account state. Parse that to tell a transient network failure from a real logout (#86).
  if let status = classifyGitHubCLIJSON(r.stdout) { return .verdict(status) }
  // Killed with nothing parseable to show for it (superseded probe, jetsam, crash, sleep/wake
  // signal): `exitCode` is a signal number, so the heuristic below would read SIGKILL as a
  // logout. That was the false, sticky "GitHub CLI not signed in".
  if r.signaled { return .keepPrior }
  // Remaining non-zero exits are a fatal gh error with no parseable JSON. Ambiguous, and
  // deliberately still reported as not-authenticated rather than silently masking a real problem.
  //
  // NOTE: one identifiable shape lands here today and is WRONG — an old gh (< 2.57) rejects
  // `--active`/`--json` outright (measured: exit 1, empty stdout, `unknown flag: --json` on
  // stderr), so a perfectly signed-in user reads as permanently logged out. That gets its own
  // `.tooOld` verdict and an upgrade message; see the PR2 hardening pass.
  return .verdict(r.ok ? .available : .notAuthenticated)
}

/// Classify `gh auth status --active --json hosts` output, or `nil` if it isn't the expected JSON
/// (so the caller can fall back). Shape: `{"hosts":{"github.com":[{"state":"success"|"error",
/// "error":"…","active":true,…}]}}`. With `--active` gh emits only each host's active account.
///
/// - No accounts at all ⇒ genuinely logged out (`.notAuthenticated`).
/// - Any active account validated (`state == "success"`) ⇒ `.available`. A success on the default
///   host means the PR/CI probes work even if a *secondary* host's account errors (issue #50).
/// - Every active account errored ⇒ distinguish the cause: a genuine auth failure (the token was
///   rejected — HTTP 401 / "bad credentials") is `.notAuthenticated`; anything else (a transport
///   error from an unreachable API, a keyring blip) is a transient failure we don't cry wolf over.
static func classifyGitHubCLIJSON(_ stdout: String) -> GitHubCLIStatus? {
  guard let data = stdout.data(using: .utf8),
    let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
    let hosts = root["hosts"] as? [String: Any]
  else { return nil }
  let accounts = hosts.values.compactMap { $0 as? [[String: Any]] }.flatMap { $0 }
  guard !accounts.isEmpty else { return .notAuthenticated }  // no accounts → logged out
  if accounts.contains(where: { ($0["state"] as? String) == "success" }) { return .available }
  let genuineFailure = accounts.contains { isGitHubAuthFailure($0["error"] as? String) }
  return genuineFailure ? .notAuthenticated : .available
}

/// Whether a `gh auth status` per-account `error` string reflects the token being *rejected* (a
/// real logout) rather than the API being *unreachable* (a transient blip). A rejected/expired
/// token gets an HTTP 401 from the API, which gh formats as `HTTP 401: Bad credentials (…)`; a
/// connectivity failure is a transport error (`Get "https://api.github.com/": …`) with no HTTP
/// status, so it falls through to "transient".
///
/// Match the 401 shape specifically (`HTTP 401` / "bad credentials") rather than a bare `401` or
/// `unauthorized` substring: those appear in unrelated text (a port, a repo name, an SSO/scope
/// 403) and would mis-gate a logged-in user back to the false warning #86 fixes. A 403 (SSO /
/// missing scope) is deliberately NOT treated as a logout — it's not a sign-in problem, and "not
/// signed in" would misdiagnose it; it falls through to transient like any other non-401 error.
static func isGitHubAuthFailure(_ error: String?) -> Bool {
  guard let e = error?.lowercased() else { return false }
  return e.contains("http 401") || e.contains("bad credentials")
}

/// Shared preflight for the two `gh` read probes (CI runs, PR list): distinguishes a transient
/// blip (timeout / rate-limit / 503 → `keepPrior`, so the badge doesn't flicker) from a hard
/// absence (gh not installed / auth failure / no remote → `absent`) from "proceed and parse"
/// (`proceed`). Both classifiers must treat gh's failure modes identically — sharing this keeps
/// them from drifting.
enum GHPreflight: Equatable {
  case proceed
  case absent
  case keepPrior
}

static func ghPreflight(_ r: CommandResult) -> GHPreflight {
  if r.timedOut { return .keepPrior }
  // Killed rather than finished (cancelled lane, jetsam, crash, sleep/wake signal): `exitCode` is
  // a signal number, so `!r.ok` below would read SIGKILL as "gh failed" and clear a good PR/CI
  // badge. Belt is the callers' `Task.isCancelled` guards (`:153`/`:156`/`:166`/`:169`); this is
  // braces, because those guards are non-local and a future call site can forget them — which is
  // exactly how the gh *auth* probe came to publish a killed child's verdict.
  if r.signaled { return .keepPrior }
  if r.exitCode == CommandResult.commandNotFound { return .absent }  // gh not installed
  let lowerErr = r.stderr.lowercased()
  if lowerErr.contains("rate limit") || lowerErr.contains("503") || lowerErr.contains("timeout") {
    return .keepPrior
  }
  if !r.ok { return .absent }  // auth failure, no remote, not a gh repo, etc.
  return .proceed
}

/// Decode the `checkRollupQuery` response into a single CI state (#76). `gh api graphql` exits 0
/// even when the body carries a GraphQL `errors` payload (the HTTP was 200), and non-zero on
/// transport failures (auth / rate-limit / 5xx) — so `ghPreflight` is the right gate here (unlike
/// `gh pr checks`, which overloads its exit code). A GraphQL `errors` payload or malformed JSON ⇒
/// `.keepPrior` (don't blank a good badge on a transient/schema blip, matching the other
/// classifiers); a null `resource`/`statusCheckRollup` ⇒ `.absent` (the commit has no checks).
static func classifyCheckRollup(_ r: CommandResult) -> CIResolution {
  switch ghPreflight(r) {
  case .absent: return .absent
  case .keepPrior: return .keepPrior
  case .proceed: break
  }

  struct Rollup: Decodable { let state: String? }
  struct Object: Decodable { let statusCheckRollup: Rollup? }
  struct Repository: Decodable { let object: Object? }
  struct DataT: Decodable { let repository: Repository? }
  struct GQLError: Decodable { let message: String? }
  struct Payload: Decodable {
    let data: DataT?
    let errors: [GQLError]?
  }
  guard let data = r.stdout.data(using: .utf8),
    let payload = try? JSONDecoder().decode(Payload.self, from: data)
  else { return .keepPrior }  // malformed/truncated → keep last good (like classifyPR)
  // A GraphQL `errors` payload (HTTP 200) is a transient/lookup error → don't blank a good badge.
  if let errors = payload.errors, !errors.isEmpty { return .keepPrior }

  // `object` null (commit not found yet) or `statusCheckRollup` null (no checks) ⇒ nothing to show.
  guard let state = payload.data?.repository?.object?.statusCheckRollup?.state else {
    return .absent
  }
  // GraphQL `StatusState`: SUCCESS / FAILURE / ERROR / PENDING / EXPECTED. Rollup folds
  // skipped/neutral into SUCCESS, so this path never yields `.neutral` (the panel's `checksSummary`
  // still distinguishes it). An unknown/future value ⇒ `.absent` rather than a misleading glyph.
  switch state.uppercased() {
  case "SUCCESS": return .state(.passing)
  case "FAILURE", "ERROR": return .state(.failing)
  case "PENDING", "EXPECTED": return .state(.running)
  default: return .absent
  }
}

/// Decode `gh pr list --head <branch> --state all --json … --limit 1` (a JSON array) into the
/// first PR, mapping GitHub's UPPER_SNAKE `state`/`reviewDecision` to our enums. An empty array is
/// `.absent` (no PR); a transient rate-limit is `.keepPrior` so the section doesn't flicker.

import Foundation

/// What a CI probe decided. `keepPrior` means "don't overwrite the last good value" (a
/// transient rate-limit / network blip), so a flaky `gh` doesn't flicker the badge to nothing.
enum CIResolution: Equatable, Sendable {
  case state(CIState)
  case absent  // gh missing/unauth, no remote, no runs, or runs are for a different commit
  case keepPrior
}

/// What a PR probe decided. `keepPrior` (transient rate-limit/network blip) keeps the last good PR
/// so a flaky `gh` doesn't flicker the Pull Request section to empty.
enum PRResolution: Equatable, Sendable {
  case info(PullRequestInfo)
  case absent  // gh missing/unauth, no remote, or no PR for the branch
  case keepPrior
}

/// What a PR-checks probe decided (issue #75). `list([])` is a valid "loaded, no checks" result —
/// distinct from `absent`. `keepPrior` (transient rate-limit/network blip) keeps the last good list
/// so a flaky `gh` doesn't flicker the panel's check rows.
enum ChecksResolution: Equatable, Sendable {
  case list([CICheck])
  case absent  // gh missing/unauth, no remote, or no checks reported
  case keepPrior
}

/// Resolves a workroom's VCS + CI status app-side by shelling to git/jj/gh. App-side (not in
/// the `workroom --json` contract) for the same reasons as `BranchResolver`: GUI-only, keeps
/// `list` instant, isolates a slow repo to its own row. Stage 1 (`resolveLocal`) is fast/local;
/// stage 2 (`resolveCI`) is the slow network call and runs separately so it never blocks the
/// dirty dot. Pure parsers are `static` so they're unit-tested without spawning anything.
struct WorkroomStatusResolver: Sendable {
  let runner: StatusCommandRunning
  var timeout: TimeInterval  // local git/jj
  var ciTimeout: TimeInterval  // gh (network)
  /// Serializes jj working-copy snapshots per project root (see `JJSnapshotGate`) — a project's
  /// workrooms share a backing repo, so concurrent snapshots can contend on it.
  var gate: JJSnapshotGate

  /// How long `resolveJJ` waits its turn behind other same-project jj snapshots, before the row
  /// reports `.timeout`. Deliberately larger than `timeout`: with the gate serializing a busy
  /// project's workrooms, a healthy repo can sit queued behind several real (not contended)
  /// snapshots — this budgets the *wait*, not any single native call (which stays un-timed inside
  /// the gate; see `JJSnapshotGate`'s doc on why timing the operation itself would be unsafe).
  static let jjGatedWaitTimeout: TimeInterval = 15

  init(
    runner: StatusCommandRunning = StatusCommandRunner(), timeout: TimeInterval = 3,
    ciTimeout: TimeInterval = 10, gate: JJSnapshotGate = .shared
  ) {
    self.runner = runner
    self.timeout = timeout
    self.ciTimeout = ciTimeout
    self.gate = gate
  }

  /// `-c` overrides prepended to every `git` invocation. A workroom can be a clone of an *untrusted*
  /// repo, and the status sweep runs git automatically on load/focus/selection — without this, a
  /// repo-local `core.fsmonitor` runs an arbitrary program on a plain `git status`. The diff probe
  /// additionally passes `--no-ext-diff`/`--no-textconv` (and the runner unsets `GIT_EXTERNAL_DIFF`)
  /// so `diff.external`/textconv config can't execute either. These flags go before the subcommand.
  static let gitHardening = ["-c", "core.fsmonitor="]

  // MARK: Stage 1 — local VCS status

  /// `projectRoot` is the colocated project root (`StatusWorkItem.projectRoot`) — required, not
  /// defaulted, so every call site is forced to supply the key `resolveJJ`'s snapshot gate needs;
  /// `resolveGit` ignores it (git reads are never gated).
  func resolveLocal(path: String, vcs: String, projectRoot: String) async -> WorkroomStatus {
    guard FileManager.default.fileExists(atPath: path) else {
      return WorkroomStatus(dirty: nil, failure: .missingPath)
    }
    switch vcs {
    case "git": return await resolveGit(path)
    case "jj": return await resolveJJ(path, projectRoot: projectRoot)
    default: return WorkroomStatus(dirty: nil, failure: .notRepository)
    }
  }

  /// Which "unknown" badge a typed backend error earns. Pure, so the mapping is unit-tested without
  /// a repo.
  ///
  /// Only the two states a *retry* can clear get their own badge: the working-copy lock being held
  /// (`.busy`) and a working copy that moved under the read (`.staleWorkingCopy`) — both raised by
  /// the jj core's snapshot, both self-describing in the sidebar tooltip and the Changes panel.
  /// Everything else stays `.notRepository`, which is also the honest answer for the common git case:
  /// `GitProvider` can't bind SwiftGitX's typed error (a Swift 6 SIL crash — see its doc), so a
  /// missing/broken repo arrives as `.io` and must keep reading as "not a repository".
  static func failure(for error: VCSError) -> VCSStatusFailure {
    switch error {
    case .lockContention: return .busy
    case .staleSnapshot: return .staleWorkingCopy
    case .unsupportedRepo, .notFound, .partialData, .backendVersion, .io: return .notRepository
    }
  }

  private func resolveGit(_ dir: String) async -> WorkroomStatus {
    // Read git status structurally through libgit2 (SwiftGitX) instead of shelling `git status` +
    // `git diff --shortstat`. `VCSProviding` has no built-in timeout, so bound the (synchronous,
    // off-main) read with `withTimeout` — a wedged repo abandons only its own row.
    let root = URL(fileURLWithPath: dir, isDirectory: true)
    do {
      let ws = try await withTimeout(seconds: timeout) {
        // `runBlocking` (GCD), NOT `Task.detached`: the cooperative pool is fixed-width and this read
        // is fanned out ~5-wide per sweep (`runLocalSweep`), overlapping History/diff/branch reads —
        // exactly the burst the `runBlocking` doc flags as the "History loads forever" starvation.
        try await runBlocking { try GitProvider().workingStatus(root: root) }
      }
      return WorkroomStatus(
        dirty: ws.dirty, conflicted: ws.conflicted, changedFiles: ws.files,
        insertions: ws.insertions, deletions: ws.deletions, branchForCI: ws.branch)
    } catch is VCSTimeoutError {
      return WorkroomStatus(dirty: nil, failure: .timeout)
    } catch let error as VCSError {
      return WorkroomStatus(dirty: nil, failure: Self.failure(for: error))
    } catch {
      return WorkroomStatus(dirty: nil, failure: .notRepository)
    }
  }

  private func resolveJJ(_ dir: String, projectRoot: String) async -> WorkroomStatus {
    // Read the jj working-copy status structurally through the Rust core (jj-lib): it snapshots `@`
    // (so it reflects disk) and returns the `@`/`@-` change sets, the ± line counts and the CI branch
    // — replacing the old serial-snapshot-then-concurrent-CLI-reads dance. ONE read, deliberately: the
    // counts used to come from a `jj diff -r @ --stat` process fired after this one, which stated them
    // against a merge `@`'s auto-merged parents (a different base than the file list) and could be
    // read across an intervening edit. `VCSProviding` has no built-in timeout, so
    // bound the (synchronous, off-main) read with `withTimeout` — for `resolveGit` a wedged repo
    // abandons only its own caller. For THIS jj path that's no longer the full story: the read is
    // additionally serialized per project root through `gate` (the ONE jj read that mutates — takes
    // the working-copy lock, can commit a repo-level transaction — and a project's workrooms share
    // that repo-level store, so concurrent snapshots across them can contend; see `JJSnapshotGate`'s
    // doc). A genuinely wedged (never-returning) native call therefore doesn't just abandon its own
    // caller — it can block later same-project calls too, bounded by `JJSnapshotGate.maxChainWait`
    // (the gate self-heals past a hung predecessor instead of queuing behind it forever). `resolveGit`
    // and `log`/`changeset`/`currentRef` (`BranchResolver`) are read-only and never gated, so they're
    // unaffected.
    let root = URL(fileURLWithPath: dir, isDirectory: true)
    do {
      return try await withTimeout(seconds: Self.jjGatedWaitTimeout) {
        try await self.gate.run(projectRoot: projectRoot) {
          // `runBlocking` (GCD), NOT `Task.detached` — the blocking, snapshot-taking jj-lib read
          // must stay off the fixed-width cooperative pool (see `resolveGit` / the `runBlocking`
          // doc). Left un-timed inside the gate on purpose — see `JJSnapshotGate`'s doc.
          try await runBlocking { try RustJJProvider().workingStatus(root: root) }
        }
      }
    } catch is VCSTimeoutError {
      return WorkroomStatus(dirty: nil, failure: .timeout)
    } catch let error as VCSError {
      return WorkroomStatus(dirty: nil, failure: Self.failure(for: error))
    } catch {
      return WorkroomStatus(dirty: nil, failure: .notRepository)
    }
  }

  // MARK: Stage 2 — CI (slow, network; never blocks stage 1)

  /// CI for `branch` (stage 1's branch/bookmark), as GitHub's own combined **status check rollup**
  /// for the branch-tip commit — the same aggregate the GitHub UI shows, covering *all* check types
  /// (Actions check-runs + external commit statuses + check-run apps), not just Actions runs (#76).
  ///
  /// `vcs`/`projectRoot` pick where `gh` runs (`ghProbeTarget`; jj → colocated project root). The
  /// commit is `ciMatchCommit`'s tip (for jj that's the bookmark's tip, since `@` is an unpushed
  /// empty change). `nameWithOwner` (`owner/repo`) keys the GraphQL `repository(owner:name:)` lookup;
  /// pass it from the sweep's per-project cache, or leave `nil` to resolve it inline (one extra
  /// `gh repo view`). Everything goes through the authenticated `gh` token, so private repos work
  /// with no extra config. CI is hidden whenever the branch / commit / repo / gh context can't be
  /// resolved.
  func resolveCI(
    path: String, vcs: String, projectRoot: String, branch: String?, nameWithOwner: String? = nil
  ) async -> CIResolution {
    guard
      let target = await ghProbeTarget(
        path: path, vcs: vcs, projectRoot: projectRoot, branch: branch)
    else { return .absent }
    guard let head = await ciMatchCommit(path: path, vcs: vcs, branch: target.branch) else {
      return .absent
    }
    // Use the caller's cached `owner/repo` when given (the sweep's per-project cache); otherwise
    // resolve it inline. (`??` can't wrap an `await` — its rhs is a non-async autoclosure.)
    let resolvedNWO: String?
    if let nameWithOwner {
      resolvedNWO = nameWithOwner
    } else {
      resolvedNWO = await resolveNameWithOwner(in: target.dir)
    }
    guard let nwo = resolvedNWO, let slash = nwo.firstIndex(of: "/") else { return .absent }
    let owner = String(nwo[..<slash])
    let name = String(nwo[nwo.index(after: slash)...])
    guard !owner.isEmpty, !name.isEmpty else { return .absent }

    let r = await runner.run(
      "gh",
      [
        "api", "graphql", "-f",
        "query=\(Self.checkRollupQuery(owner: owner, name: name, oid: head))",
      ],
      in: target.dir, timeout: ciTimeout)
    return Self.classifyCheckRollup(r)
  }

  /// The repo's `owner/repo` for the GraphQL rollup lookup, from `gh repo view` in the probe dir
  /// (resolves via the dir's git remote — works for git worktrees and a jj colocated project root).
  /// The sweep caches this per project; `resolveCI` falls back to calling it inline. `nil` ⇒ no
  /// remote / not a gh repo ⇒ caller treats CI as absent.
  func resolveNameWithOwner(in dir: String) async -> String? {
    let r = await runner.run(
      "gh", ["repo", "view", "--json", "nameWithOwner", "-q", ".nameWithOwner"], in: dir,
      timeout: ciTimeout)
    guard r.ok else { return nil }
    let s = r.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
    return s.isEmpty ? nil : s
  }

  /// GraphQL query for a commit's status-check rollup state. Uses `repository(owner:name:)` +
  /// `object(oid:)` so it runs against whatever host `gh` resolves for the repo (github.com or GHE),
  /// no hardcoded URL. Mirrors the `reviewURLQuery` style (interpolated, trusted inputs: repo names
  /// can't contain quotes; `oid` is a hex sha).
  static func checkRollupQuery(owner: String, name: String, oid: String) -> String {
    "{repository(owner:\"\(owner)\",name:\"\(name)\"){object(oid:\"\(oid)\"){... on Commit{statusCheckRollup{state}}}}}"
  }

  /// The pull request for `branch`. Like `resolveCI`, `vcs`/`projectRoot` pick where `gh` runs (a
  /// jj workspace has no `.git` of its own, so `gh` must run from the colocated project root). `gh
  /// pr list --head` returns a JSON array — empty when the branch has no PR — so "no PR" is a clean
  /// `.absent`, not an error.
  func resolvePR(path: String, vcs: String, projectRoot: String, branch: String?) async
    -> PRResolution
  {
    let res = await resolvePRRaw(path: path, vcs: vcs, projectRoot: projectRoot, branch: branch)
    return await enrichPR(res, path: path, vcs: vcs, projectRoot: projectRoot)
  }

  /// The classified PR (`gh pr list`) *without* the reviewer-permalink enrichment round-trip. The
  /// selection flow uses this so it has the PR `number` immediately — letting `resolveChecks` and the
  /// (slower, conditional) reviewer-URL enrichment run concurrently instead of checks waiting behind
  /// enrichment (issue #75, Codex #5). `resolvePR` composes this + `enrichPR` to preserve its old
  /// behaviour for any other caller.
  func resolvePRRaw(path: String, vcs: String, projectRoot: String, branch: String?) async
    -> PRResolution
  {
    guard
      let target = await ghProbeTarget(
        path: path, vcs: vcs, projectRoot: projectRoot, branch: branch)
    else { return .absent }

    let r = await runner.run(
      "gh",
      [
        "pr", "list", "--head", target.branch, "--state", "all", "--limit", "1", "--json",
        "number,title,state,isDraft,url,reviewDecision,latestReviews,reviewRequests,"
          + "mergeable,mergeStateStatus",
      ], in: target.dir, timeout: ciTimeout)
    return Self.classifyPR(r)
  }

  /// Attach reviewer permalinks to an already-classified PR. Runs `gh` in the same repo context as
  /// the read probes (jj → colocated project root). A no-op for `.absent`/`.keepPrior` (and for a PR
  /// with no submitted reviews — see `enrichReviewURLs`), so it's safe to call unconditionally.
  func enrichPR(_ res: PRResolution, path: String, vcs: String, projectRoot: String) async
    -> PRResolution
  {
    let dir = Self.ghProbeDirectory(path: path, vcs: vcs, projectRoot: projectRoot)
    return await enrichReviewURLs(res, in: dir)
  }

  /// The PR's individual CI checks (issue #75) via `gh pr checks <number>`. Keyed off the PR
  /// `number`, so unlike CI/PR it needs no branch resolution — just the gh repo context (jj →
  /// colocated project root, like the other probes). The pure `classifyChecks` decides from stdout
  /// regardless of exit code (see its doc), so a "pending" (exit 8) or "a check failed" (exit 1) run
  /// still yields the list rather than being misread as a hard failure.
  func resolveChecks(path: String, vcs: String, projectRoot: String, number: Int) async
    -> ChecksResolution
  {
    let dir = Self.ghProbeDirectory(path: path, vcs: vcs, projectRoot: projectRoot)
    let r = await runner.run(
      "gh",
      ["pr", "checks", "\(number)", "--json", "name,state,bucket,link,workflow"],
      in: dir, timeout: ciTimeout)
    return Self.classifyChecks(r)
  }

  /// Attach each submitted reviewer's review permalink so the PR panel can deep-link a row to its
  /// comment. `gh pr list --json` blanks review urls/ids, so fetch them with a GraphQL
  /// `resource(url:)` follow-up keyed by the PR's own URL. Best-effort: any failure (the probe
  /// errors, returns nothing, or the PR has no submitted reviews) leaves urls `nil` and returns the
  /// already-resolved PR unchanged — it never downgrades a good result. Only fires when there's a
  /// submitted (non-`requested`) reviewer, so PRs awaiting first review skip the extra round-trip.
  private func enrichReviewURLs(_ res: PRResolution, in dir: String) async -> PRResolution {
    guard case .info(let pr) = res,
      pr.reviewers.contains(where: { $0.state != .requested })
    else { return res }
    let g = await runner.run(
      "gh", ["api", "graphql", "-f", "query=\(Self.reviewURLQuery(prURL: pr.url))"],
      in: dir, timeout: ciTimeout)
    let urls = Self.parseReviewURLs(g)
    guard !urls.isEmpty else { return res }
    let enriched = pr.reviewers.map { rev -> Reviewer in
      guard case .user(let login) = rev.identity, let url = urls[login] else { return rev }
      return Reviewer(identity: rev.identity, state: rev.state, url: url)
    }
    return .info(
      PullRequestInfo(
        number: pr.number, title: pr.title, state: pr.state, isDraft: pr.isDraft, url: pr.url,
        reviewDecision: pr.reviewDecision, reviewers: enriched,
        mergeable: pr.mergeable, mergeState: pr.mergeState))
  }

  /// The GraphQL query that maps a PR's submitted reviews to their author + permalink. Keyed by the
  /// PR's web URL via `resource(url:)` so it needs no separate owner/repo lookup.
  static func reviewURLQuery(prURL: String) -> String {
    "{resource(url:\"\(prURL)\"){... on PullRequest{latestReviews(first:50){nodes{author{login} url}}}}}"
  }

  /// Decode the `reviewURLQuery` response into `login → review-permalink`. Best-effort: a non-JSON
  /// body, a GraphQL `errors` payload, or any missing field yields an empty map (urls stay `nil`),
  /// so a flaky enrichment probe never blanks the reviewer rows.
  static func parseReviewURLs(_ r: CommandResult) -> [String: String] {
    struct Author: Decodable { let login: String? }
    struct Node: Decodable {
      let author: Author?
      let url: String?
    }
    struct Reviews: Decodable { let nodes: [Node]? }
    struct Resource: Decodable { let latestReviews: Reviews? }
    struct Data: Decodable { let resource: Resource? }
    struct Payload: Decodable { let data: Data? }
    guard let data = r.stdout.data(using: .utf8),
      let payload = try? JSONDecoder().decode(Payload.self, from: data)
    else { return [:] }
    var map: [String: String] = [:]
    for node in payload.data?.resource?.latestReviews?.nodes ?? [] {
      guard let login = node.author?.login, !login.isEmpty,
        let url = node.url, !url.isEmpty
      else { continue }
      map[login] = url
    }
    return map
  }

  /// Where a stage-2 `gh` probe must run and which branch it keys off, per VCS. A **git worktree**
  /// has its own `.git`, so `gh` runs in-place (`path`) keyed by the git branch (stage-1 branch, or
  /// the colocated ref via `git symbolic-ref`). A **jj workspace** has no `.git` of its own — only
  /// the colocated `projectRoot` does — so `gh` runs from `projectRoot`, keyed by the bookmark.
  /// `nil` ⇒ no resolvable branch ⇒ caller returns `.absent`.
  private func ghProbeTarget(path: String, vcs: String, projectRoot: String, branch: String?) async
    -> (dir: String, branch: String)?
  {
    let dir = Self.ghProbeDirectory(path: path, vcs: vcs, projectRoot: projectRoot)
    if vcs == "jj" {
      guard let branch, !branch.isEmpty else { return nil }
      return (dir, branch)
    }
    guard let branchName = await resolveBranchName(branch, in: path) else { return nil }
    return (dir, branchName)
  }

  /// The directory a `gh` invocation must run in for this workroom: in-place for a git worktree
  /// (it has its own `.git` + remote), but the colocated `projectRoot` for a jj workspace (a
  /// secondary jj workspace has no `.git`, so `gh` can't resolve the repo there). Shared by the
  /// read probes (`ghProbeTarget`) and the PR write actions (`performPRAction`) so they agree.
  static func ghProbeDirectory(path: String, vcs: String, projectRoot: String) -> String {
    vcs == "jj" ? projectRoot : path
  }

  /// The commit a `gh run` must match to count as "this branch's CI". For a **git worktree** that's
  /// `HEAD` (the branch tip). For a **jj workspace** it's the bookmark's tip commit — jj's `@` is an
  /// unpushed empty change, so CI ran on the bookmark, not `@`. jj's `commit_id` is the git commit
  /// hash in a git-backed repo, so it matches `gh`'s `headSha` exactly. `nil` ⇒ unresolved ⇒ absent.
  private func ciMatchCommit(path: String, vcs: String, branch: String) async -> String? {
    let r: CommandResult
    if vcs == "jj" {
      r = await runner.run(
        "jj", ["log", "-r", branch, "--no-graph", "--color", "never", "-T", "commit_id"],
        in: path, timeout: timeout)
    } else {
      r = await runner.run(
        "git", Self.gitHardening + ["rev-parse", "HEAD"], in: path, timeout: timeout)
    }
    guard r.ok else { return nil }
    let sha = r.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
    return sha.isEmpty ? nil : sha
  }

  /// The git branch CI/PR key off when not jj: the stage-1 branch when known, else the colocated
  /// git ref via `git symbolic-ref` (empty for a *detached* HEAD). Returns `nil` when neither yields
  /// a non-empty name. Faithful to the prior inline fallback: a non-nil `branch` is used as-is (the
  /// symbolic-ref probe runs only when it's nil).
  private func resolveBranchName(_ branch: String?, in path: String) async -> String? {
    var branchName = branch
    if branchName == nil {
      let b = await runner.run(
        "git", Self.gitHardening + ["symbolic-ref", "--quiet", "--short", "HEAD"], in: path,
        timeout: timeout)
      branchName = b.ok ? b.stdout.trimmingCharacters(in: .whitespacesAndNewlines) : nil
    }
    guard let branchName, !branchName.isEmpty else { return nil }
    return branchName

  static func classifyPR(_ r: CommandResult) -> PRResolution {
    switch ghPreflight(r) {
    case .absent: return .absent
    case .keepPrior: return .keepPrior
    case .proceed: break
    }

    // `latestReviews` = the latest submitted review per author; `reviewRequests` = pending reviewers
    // (users by `login`, teams by `slug`). Both optional so JSON that omits them (old/other callers)
    // decodes cleanly to an empty reviewer list — only a *present-but-malformed* payload fails the
    // whole decode and trips `.keepPrior` below, so we never silently blank reviewers on a parse error.
    struct RawAuthor: Decodable { let login: String? }
    struct RawReview: Decodable {
      let author: RawAuthor?
      let state: String?
    }
    struct RawRequest: Decodable {
      let login: String?  // present for user reviewers
      let slug: String?  // present for team reviewers (with `name`); `__typename` is ignored
    }
    struct Raw: Decodable {
      let number: Int
      let title: String
      let state: String
      let isDraft: Bool
      let url: String
      let reviewDecision: String?
      let latestReviews: [RawReview]?
      let reviewRequests: [RawRequest]?
      let mergeable: String?  // MERGEABLE / CONFLICTING / UNKNOWN (issue #88)
      let mergeStateStatus: String?  // CLEAN / BLOCKED / BEHIND / … (issue #88)
    }
    // Malformed/truncated JSON (a gh schema change, or output capped mid-stream) must NOT erase the
    // PR badge. A *valid* empty array is different — that genuinely means no PR (handled below).
    guard let data = r.stdout.data(using: .utf8),
      let raws = try? JSONDecoder().decode([Raw].self, from: data)
    else { return .keepPrior }
    guard let raw = raws.first else { return .absent }  // valid empty array ⇒ genuinely no PR

    let state: PullRequestInfo.State
    switch raw.state.uppercased() {
    case "OPEN": state = .open
    case "MERGED": state = .merged
    case "CLOSED": state = .closed
    // An unexpected/future GitHub state: keep the last good PR rather than render one we don't
    // understand — mapping it to `.open` would expose destructive actions (close/draft) on it.
    default: return .keepPrior
    }
    let review: PullRequestInfo.ReviewDecision?
    switch raw.reviewDecision?.uppercased() {
    case "APPROVED": review = .approved
    case "CHANGES_REQUESTED": review = .changesRequested
    case "REVIEW_REQUIRED": review = .reviewRequired
    default: review = nil  // "" or absent → no decision to show
    }

    // Fold the two review arrays into one list keyed by reviewer identity. `latestReviews` is the
    // latest submitted review per author (so a login appears at most once — the keyed insert is
    // idempotent). `reviewRequests` then OVERRIDES: a re-requested reviewer is pending again even if
    // a stale submitted review exists. Order is irrelevant — `PRPresentation.reviewers` sorts.
    var reviewersByID: [String: Reviewer] = [:]
    for rev in raw.latestReviews ?? [] {
      guard let login = rev.author?.login, !login.isEmpty else { continue }
      let st: Reviewer.State
      switch rev.state?.uppercased() {
      case "APPROVED": st = .approved
      case "CHANGES_REQUESTED": st = .changesRequested
      case "COMMENTED": st = .commented
      case "DISMISSED": st = .dismissed
      default: continue  // unrecognised state (e.g. a future GitHub value, PENDING) → don't render
      }
      let reviewer = Reviewer(identity: .user(login: login), state: st)
      reviewersByID[reviewer.id] = reviewer
    }
    for req in raw.reviewRequests ?? [] {
      let identity: Reviewer.Identity
      if let login = req.login, !login.isEmpty {
        identity = .user(login: login)
      } else if let slug = req.slug, !slug.isEmpty {
        identity = .team(slug: slug)
      } else {
        continue  // no usable identifier
      }
      let reviewer = Reviewer(identity: identity, state: .requested)
      reviewersByID[reviewer.id] = reviewer
    }

    // Mergeability (issue #88): `MERGEABLE`/`CONFLICTING` map to true/false; anything else
    // (`UNKNOWN`, absent) stays nil so the Merge button hides while GitHub is still computing.
    let mergeable: Bool?
    switch raw.mergeable?.uppercased() {
    case "MERGEABLE": mergeable = true
    case "CONFLICTING": mergeable = false
    default: mergeable = nil
    }
    let mergeState: PullRequestInfo.MergeState?
    switch raw.mergeStateStatus?.uppercased() {
    case "CLEAN": mergeState = .clean
    case "BLOCKED": mergeState = .blocked
    case "BEHIND": mergeState = .behind
    case "UNSTABLE": mergeState = .unstable
    case "DIRTY": mergeState = .dirty
    case "DRAFT": mergeState = .draft
    case "HAS_HOOKS": mergeState = .hasHooks
    case "UNKNOWN": mergeState = .unknown
    case .some: mergeState = .unknown  // a future value → not-yet-mergeable, never misread as clean
    case nil: mergeState = nil
    }

    return .info(
      PullRequestInfo(
        number: raw.number, title: raw.title, state: state, isDraft: raw.isDraft, url: raw.url,
        reviewDecision: review, reviewers: Array(reviewersByID.values),
        mergeable: mergeable, mergeState: mergeState))
  }

  /// Decode `gh pr checks <n> --json name,state,bucket,link,workflow` into the per-check list.
  ///
  /// CRITICAL: `gh pr checks` overloads its exit code — `8` = checks pending, `1` = a check *failed*
  /// OR no-checks/other error, `0` = all pass — yet it still writes the JSON array to stdout for the
  /// pending/failing cases. So this decides from the JSON, NOT the exit code, and deliberately does
  /// NOT use `ghPreflight` (whose `!r.ok ⇒ .absent` rule is exactly wrong here). Parse stdout first;
  /// only when there's no usable JSON do we fall back to gh's failure modes (missing/blip/absent).
  ///
  /// A valid empty array (`[]`) ⇒ `.absent` ("loaded, no checks" — the store maps it to `[]`). A
  /// transient blip with no stdout ⇒ `.keepPrior` so the rows don't flicker.
  static func classifyChecks(_ r: CommandResult) -> ChecksResolution {
    struct Raw: Decodable {
      let name: String?
      let bucket: String?
      let state: String?
      let link: String?
      let workflow: String?
    }
    let trimmed = r.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
    if !trimmed.isEmpty {
      guard let data = r.stdout.data(using: .utf8),
        let raws = try? JSONDecoder().decode([Raw].self, from: data)
      else {
        // Non-empty but unparseable (truncated output / a gh schema change) must NOT blank the rows
        // — keep the last good list, like classifyCI/classifyPR do for malformed JSON.
        return .keepPrior
      }
      let checks: [CICheck] = raws.compactMap { raw in
        guard let name = raw.name, !name.isEmpty else { return nil }
        return CICheck(
          name: name,
          state: Self.checkState(bucket: raw.bucket),
          workflow: raw.workflow.flatMap { $0.isEmpty ? nil : $0 },
          link: raw.link.flatMap { $0.isEmpty ? nil : $0 })
      }
      // Empty array, or rows that all lacked a usable name ⇒ genuinely no checks to show.
      return checks.isEmpty ? .absent : .list(checks)
    }
    // Empty stdout (gh wrote nothing): distinguish gh-missing / transient blip / hard absence.
    if r.timedOut { return .keepPrior }
    if r.exitCode == CommandResult.commandNotFound { return .absent }  // gh not installed
    let lowerErr = r.stderr.lowercased()
    if lowerErr.contains("rate limit") || lowerErr.contains("503") || lowerErr.contains("timeout") {
      return .keepPrior
    }
    return .absent  // no checks reported / auth failure / no remote / etc.
  }

  /// gh's normalized `bucket` → our `CICheck.State`. Unknown ⇒ `.skipped` (quiet) so a future gh
  /// bucket value still renders a row rather than vanishing.
  static func checkState(bucket: String?) -> CICheck.State {
    switch bucket?.lowercased() {
    case "pass": return .passing
    case "fail": return .failing
    case "pending": return .pending
    case "skipping": return .skipped
    case "cancel": return .cancelled
    default: return .skipped
    }
  }
}

  guard !result.ok else { return nil }
  if err.contains("Host key verification failed") || err.contains("REMOTE HOST IDENTIFICATION") {
    return .hostKeyUnverified(err)
  }
  if err.contains("terminal prompts disabled") || err.contains("could not read Username")
    || err.contains("could not read Password") || err.contains("Authentication failed")
    || err.contains("Permission denied (publickey)")
  {
    return .authRequired(err)
  }
  if err.contains("would be overwritten") { return .dirtyWorkingTree(err) }
  if err.contains("does not appear to be a git repository") || err.contains("No such remote")
    || err.contains("no such remote") || err.contains("No git remotes")
  {
    return .noRemote
  }
  // Flag column first, prose second. The string checks stay as a fallback rather than being replaced:
  // `--porcelain` is ours to pass on the push path only, so a rejection surfaced by any other route
  // (a remote helper, a future caller that forgets the flag) still classifies.
  if gitPushRejected(stdout: result.stdout) || err.contains("Updates were rejected")
    || err.contains("! [rejected]")
  {
    return .rejected(err)
  }
  // Both jj-only, and both permanent until the user acts — so they must NOT reach `.other`, whose
  // recovery is a retry of the same doomed command. jj doesn't localize, so matching its prose is safe
  // here in a way it wouldn't be for git.
  if err.contains("since it has no description") || err.contains("has no description") {
    return .needsDescription(err)
  }
  if err.contains("is immutable") || err.contains("immutable commits") {
    return .immutableHistory(err)
  }
  if err.contains("Failed to take lock for Git import/export")
    || (err.contains(".lock")
      && (err.contains("could not be obtained") || err.contains("File exists")
        || err.contains("Unable to create")))
  {
    return .locked(lockFile(in: err))
  }
  if action == .pull, rebaseInProgress(gitDir: gitDir) { return .rebaseInProgress }
  // A lock failure that never names a lock. git's message depends on WHICH internal step hit the lock:
  // a fast-forward pull reports `Unable to create '<path>': File exists.`, but a pull that must really
  // rebase fails in autostash first and says only `error: could not write index` / `fatal: Cannot
  // autostash` — no path, no "lock", nothing the checks above can match. That is the diverged pull,
  // i.e. exactly what the toolbar's Pull button is for, and it was landing in `.other` with raw stderr.
  //
  // So when the symptoms are lock-shaped, ask the DISK instead of the message. Deliberately last: any
  // failure git explains properly keeps its own classification, and this only speaks for the ones it
  // doesn't.
  if lockSymptom(err), let lock = existingLockFile(gitDir: gitDir) { return .locked(lock) }
  let trimmed = err.trimmingCharacters(in: .whitespacesAndNewlines)
  // Killed rather than finished, with nothing to say for itself: `exitCode` is the SIGNAL number,
  // so the fallback below would render "git exited 15" — literally the dialog `a64e4269` ("stop
  // 'exited with code 15' dialog on wake from sleep") set out to end. That fix taught
  // `WorkroomCLI.CLIResult` about signals but never reached this runner. Deliberately last, and
  // only when there is no stderr: a child that explained itself before dying keeps its real
  // classification. `.other` retries, which is the right recovery for an interrupted write.
  if trimmed.isEmpty, result.signaled { return .other("\(tool) was interrupted") }
  return .other(trimmed.isEmpty ? "\(tool) exited \(result.exitCode)" : trimmed)
}

/// Signing failures. With `standardInput` on `/dev/null` gpg cannot reach a TTY pinentry, so it
/// fails FAST with these rather than hanging — which is why the plan carries no signing preflight:
/// predicting whether pinentry needs a terminal is undecidable (it depends on `gpg-agent.conf`,
/// the agent's cache state and whether a smartcard is present), and this is decidable.
static let commitSigningMarkers = [
  "gpg failed to sign the data", "failed to write commit object",
  "Inappropriate ioctl for device", "error: unable to sign the commit",
  "user.signingkey", "secret key not available",
]

/// Missing `user.name`/`user.email`. git's own message tells the user exactly what to run, so the
/// value is carried through rather than replaced.
static let commitIdentityMarkers = [
  "Please tell me who you are", "unable to auto-detect email address",
  "empty ident name", "no email was given",
]

/// git's phrasings, matched only on the FAILURE path — see `classifyCommit`. jj's exit-zero no-op
/// is not in here on purpose; it needs the whole-line check below.
static let commitNothingMarkers = [
  "nothing to commit", "no changes added to commit", "nothing added to commit",
]

/// jj's no-op marker, as a whole line rather than a substring.
///
/// jj echoes the change's description back in its `Working copy (@) now at:` and `Parent commit
/// (@-)` lines, so a `contains` here would fire on any commit whose own message happened to carry
/// the phrase — reporting a successful write as a no-op.
/// Both streams are checked. jj 0.43 writes this (and everything else) to stderr, but the whole-line
/// anchor is what makes the match safe, not the choice of stream — so covering stdout too costs
/// nothing and survives jj moving it.
static func saysNothingChanged(_ result: CommandResult) -> Bool {
  let lines = (result.stderr + "\n" + result.stdout).split(
    separator: "\n", omittingEmptySubsequences: false)
  return lines.contains { $0.trimmingCharacters(in: .whitespaces) == "Nothing changed." }
}

static let commitUnmergedMarkers = [
  "you have unmerged files", "Committing is not possible because you have unmerged files",
  "needs merge",
]

/// Hook rejection. **An explicit marker set, never the `else` branch.** A catch-all here would
/// relabel signing failures, bad config, index corruption and message-policy errors as "a hook
/// rejected this", which is worse than saying nothing: it sends the user to edit a hook that was
/// never involved. Anything unmatched stays `.other`, carrying git's own words.
static let commitHookMarkers = [
  "hook declined", "pre-commit hook", "commit-msg hook", "prepare-commit-msg hook",
  "hook exited with", "hook returned",
]

/// Map a failed commit to a typed failure. `nil` means success.
///
/// `movedRef` says the ref changed even though the command reported failure — the caller turns
/// that into `.committedThenFailed` rather than a failure, because retrying would make a SECOND
/// commit. The reachable case is a `post-commit` hook: git has already written the commit and
/// moved `HEAD` by the time it runs, so a hook that fails or runs past the timeout leaves a
/// perfectly good commit behind a non-zero exit.
static func classifyCommit(_ result: CommandResult, tool: String) -> VCSCommitFailure? {
  if result.exitCode == CommandResult.commandNotFound { return .toolMissing(tool) }
  // jj says "Nothing changed." and exits ZERO, so its no-op has to be read BEFORE the success
  // guard — an untouched working copy must not be reported as a commit that happened.
  //
  // Scoped to jj, matched on a whole stderr line, and never against stdout. All three matter:
  // `git commit` echoes the SUBJECT on stdout, so the substring form this replaces classified
  // `-m "explain the nothing to commit error"` — a commit that succeeded, exit 0 — as a failure,
  // and `commit()` then upgraded it to `.committedThenFailed` because the ref had legitimately
  // moved. The dialog told the user their commit had half-worked when it was perfect. jj puts
  // everything on stderr including its own echo of the description (`Parent commit (@-) … <msg>`),
  // hence the whole-line anchor rather than `contains`. Measured on git 2.55 / jj 0.43.
  if tool == "jj", result.ok, saysNothingChanged(result) { return .nothingToCommit }
  if result.timedOut { return .timedOut }
  guard !result.ok else { return nil }

  // Only now, on a genuine failure, is matching the combined output safe: git's own
  // "nothing to commit, working tree clean" goes to stdout with a non-zero exit.
  let err = result.stderr + "\n" + result.stdout
  if commitNothingMarkers.contains(where: err.contains) { return .nothingToCommit }
  if commitIdentityMarkers.contains(where: err.contains) { return .identityMissing(err) }
  if commitSigningMarkers.contains(where: err.contains) { return .signingFailed(err) }
  if commitUnmergedMarkers.contains(where: err.contains) { return .unmergedFiles(err) }
  // Before the hook check: git phrases this one as a plain fatal, and it is a state the user must
  // finish rather than a hook they must fix.
  if err.contains("cannot do a partial commit during a") || err.contains("is in progress") {
    return .sequencerInProgress(err)
  }
  if commitHookMarkers.contains(where: err.contains) { return .hookRejected(err) }
  if err.contains("Failed to take lock") || err.contains("index.lock")
    || (err.contains(".lock")
      && (err.contains("could not be obtained") || err.contains("File exists")
        || err.contains("Unable to create")))
  {
    return .locked(lockFile(in: err))
  }
  let trimmed = err.trimmingCharacters(in: .whitespacesAndNewlines)
  // Same reasoning as `classify`: a signal number is not an exit status, so don't print it as one.
  if trimmed.isEmpty, result.signaled { return .other("\(tool) was interrupted") }
  return .other(trimmed.isEmpty ? "\(tool) exited \(result.exitCode)" : trimmed)
}

/// Whether a rebase is parked in this worktree. Both directory names are checked: `rebase-merge` for
/// an interactive/merge rebase, `rebase-apply` for the am-based one.
static func rebaseInProgress(gitDir: URL?) -> Bool {
  guard let gitDir else { return false }
  let fm = FileManager.default
  return fm.fileExists(atPath: gitDir.appendingPathComponent("rebase-merge").path)
    || fm.fileExists(atPath: gitDir.appendingPathComponent("rebase-apply").path)
}

/// Which multi-step git operation is parked in this worktree, named for the user, or nil if none.
///
/// Checking for *conflicts* is not enough, and the difference is a real trap: resolving the
/// conflicts in a terminal clears the conflict markers but leaves `MERGE_HEAD` sitting there, so a
/// conflict-only guard re-enables Commit into a guaranteed `fatal: cannot do a partial commit
/// during a merge`. The sequencer file is the durable fact; the conflict is not.
///
/// Ordered by specificity: a cherry-pick and a revert both also leave `MERGE_HEAD` behind, so they
/// are tested first or every one of them would report "merge".
static func sequencerState(gitDir: URL?) -> String? {
  guard let gitDir else { return nil }
  let fm = FileManager.default
  let markers: [(String, String)] = [
    ("CHERRY_PICK_HEAD", "cherry-pick"),
    ("REVERT_HEAD", "revert"),
    ("rebase-merge", "rebase"),
    ("rebase-apply", "rebase"),
    ("BISECT_LOG", "bisect"),
    ("MERGE_HEAD", "merge"),
  ]
  for (file, label) in markers
  where fm.fileExists(atPath: gitDir.appendingPathComponent(file).path) {
    return label
  }
  return nil
}

